258	/****************************************************************************
259	 * Private Functions - WebSocket framing
260	 ****************************************************************************/
261	
262	/* Generate a random 4-byte masking key. mbedtls_ctr_drbg_random is used as
263	 * a random source (no Date.now/random needed).
264	 */
265	static void ws_make_mask(uint8_t mask[4], struct xiaozhi_ws_s *ws)
266	{
267	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, mask, 4);
268	}
269	
270	/* Send one client->server frame (masked). */
271	static int ws_send_frame(struct xiaozhi_ws_s *ws, uint8_t opcode,
272	                         const uint8_t *data, size_t len)
273	{
274	  uint8_t hdr[14];
275	  size_t hdrlen;
276	  uint8_t mask[4];
277	  int ret;
278	
279	  hdr[0] = WS_FIN_BIT | opcode;
280	
281	  if (len <= 125)
282	    {
283	      hdr[1] = WS_MASK_BIT | (uint8_t)len;
284	      hdrlen = 2;
285	    }
286	  else if (len <= 65535)
287	    {
288	      hdr[1] = WS_MASK_BIT | 126;
289	      hdr[2] = (len >> 8) & 0xff;
290	      hdr[3] = len & 0xff;
291	      hdrlen = 4;
292	    }
293	  else
294	    {
295	      /* 64-bit length path. Opus/JSON frames are never this large, but
296	       * implement for completeness.
297	       */
298	      hdr[1] = WS_MASK_BIT | 127;
299	      uint64_t l = len;
300	      hdr[2] = 0; hdr[3] = 0; hdr[4] = 0; hdr[5] = 0;
301	      hdr[6] = (l >> 24) & 0xff;
302	      hdr[7] = (l >> 16) & 0xff;
303	      hdr[8] = (l >> 8) & 0xff;
304	      hdr[9] = l & 0xff;
305	      hdrlen = 10;
306	    }
307	
308	  ret = ws_tls_write_all(ws, hdr, hdrlen);
309	  if (ret != 0)
310	    {
311	      return ret;
312	    }
313	
314	  /* Masking key + masked payload. */
315	  ws_make_mask(mask, ws);
316	  ret = ws_tls_write_all(ws, mask, 4);
317	  if (ret != 0)
318	    {
319	      return ret;
320	    }
321	
322	  if (len > 0)
323	    {
324	      /* XOR the payload in a stack buffer to keep rxbuf/data const.
325	       * For large frames a streaming XOR would be better; xiaozhi payloads
326	       * are small (Opus <= ~400B, JSON <= ~2KB).
327	       */
328	      uint8_t masked[1];
329	      for (size_t i = 0; i < len; i++)
330	        {
331	          masked[0] = data[i] ^ mask[i & 3];
332	          ret = ws_tls_write_all(ws, masked, 1);
333	          if (ret != 0)
334	            {
335	              return ret;
336	            }
337	        }
338	    }
339	
340	  return 0;
341	}
