343	/****************************************************************************
344	 * Public Functions
345	 ****************************************************************************/
346	
347	int xiaozhi_ws_connect(struct xiaozhi_ws_s *ws, const char *ws_url,
348	                       const char *token, const char *device_id,
349	                       const char *client_id)
350	{
351	  char host[128];
352	  char path[256];
353	  char portstr[8];
354	  const char *p;
355	  const char *hoststart;
356	  const char *hostend;
357	  const char *pathstart;
358	  int port = 443;
359	  int ret;
360	  uint8_t wskey[16];
361	  char req[768];
362	
363	  memset(ws, 0, sizeof(*ws));
364	  ws->fd = -1;
365	
366	  /* Parse "wss://host[:port]/path..." */
367	  if (strncmp(ws_url, "wss://", 6) != 0)
368	    {
369	      printf("[xiaozhi] ws url must be wss://: %s\n", ws_url);
370	      return -EINVAL;
371	    }
372	
373	  hoststart = ws_url + 6;
374	  pathstart = strchr(hoststart, '/');
375	  hostend   = pathstart ? pathstart : hoststart + strlen(hoststart);
376	
377	  /* Detect port in host portion */
378	  p = memchr(hoststart, ':', hostend - hoststart);
379	  if (p != NULL)
380	    {
381	      size_t hlen = p - hoststart;
382	      memcpy(host, hoststart, hlen);
383	      host[hlen] = '\0';
384	      port = atoi(p + 1);
385	    }
386	  else
387	    {
388	      size_t hlen = hostend - hoststart;
389	      memcpy(host, hoststart, hlen);
390	      host[hlen] = '\0';
391	    }
392	
393	  snprintf(portstr, sizeof(portstr), "%d", port);
394	
395	  if (pathstart)
396	    {
397	      snprintf(path, sizeof(path), "%s", pathstart);
398	    }
399	  else
400	    {
401	      path[0] = '/'; path[1] = '\0';
402	    }
403	
404	  printf("[xiaozhi] ws host=%s port=%d path=%s token=%s\n",
405	         host, port, path, token);
406	
407	  /* Allocate rx buffer. */
408	  ws->rxbuf_cap = WS_RXBUF_SIZE;
409	  ws->rxbuf = malloc(ws->rxbuf_cap);
410	  if (ws->rxbuf == NULL)
411	    {
412	      return -ENOMEM;
413	    }
414	
415	  /* TLS init + connect. */
416	  ret = ws_tls_init(ws);
417	  if (ret != 0)
418	    {
419	      return ret;
420	    }
421	
422	  ret = ws_tls_connect(ws, host, portstr);
423	  if (ret != 0)
424	    {
425	      return ret;
426	    }
427	
428	  /* WebSocket HTTP Upgrade handshake. */
429	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, wskey, 16);
430	
431	  /* Build Sec-WebSocket-Key (base64 of 16 random bytes). We use a tiny
432	   * base64 encoder below.
433	   */
434	  char wskey_b64[32];
435	  {
436	    const char b64[] =
437	      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
438	    int o = 0;
439	    int i;
440	    for (i = 0; i < 16; i += 3)
441	      {
442	        uint32_t v = (wskey[i] << 16);
443	        if (i + 1 < 16) v |= (wskey[i + 1] << 8);
444	        if (i + 2 < 16) v |= wskey[i + 2];
445	        wskey_b64[o++] = b64[(v >> 18) & 0x3f];
446	        wskey_b64[o++] = b64[(v >> 12) & 0x3f];
447	        wskey_b64[o++] = (i + 1 < 16) ? b64[(v >> 6) & 0x3f] : '=';
448	        wskey_b64[o++] = (i + 2 < 16) ? b64[v & 0x3f] : '=';
449	      }
450	
451	    wskey_b64[o] = '\0';
452	  }
453	
454	  snprintf(req, sizeof(req),
455	    "GET %s HTTP/1.1\r\n"
456	    "Host: %s\r\n"
457	    "Upgrade: websocket\r\n"
458	    "Connection: Upgrade\r\n"
459	    "Sec-WebSocket-Key: %s\r\n"
460	    "Sec-WebSocket-Version: 13\r\n"
461	    "Authorization: Bearer %s\r\n"
462	    "Device-Id: %s\r\n"
463	    "Client-Id: %s\r\n"
464	    "Protocol-Version: 1\r\n"
465	    "\r\n",
466	    path, host, wskey_b64, token, device_id, client_id);
467	
468	  printf("[xiaozhi] sending ws upgrade request (%zu bytes)\n", strlen(req));
469	
470	  ret = ws_tls_write_all(ws, (const uint8_t *)req, strlen(req));
471	  if (ret != 0)
472	    {
473	      return ret;
474	    }
475	
476	  /* Read the HTTP response line + headers until blank line. */
477	  {
478	    char line[256];
479	    int got101 = 0;
480	
481	    /* Read line-by-line until \r\n\r\n */
482	    for (;;)
483	      {
484	        size_t li = 0;
485	        char prev = 0;
486	
487	        while (li < sizeof(line) - 1)
488	          {
489	            uint8_t b;
490	            ret = ws_tls_read_all(ws, &b, 1);
491	            if (ret != 0)
492	              {
493	                return ret;
494	              }
495	
496	            line[li] = (char)b;
497	            if (line[li] == '\n' && prev == '\r')
498	              {
499	                break;
500	              }
501	
502	            prev = line[li];
503	            li++;
504	          }
505	
506	        line[li] = '\0';
507	
508	        /* Strip trailing \r\n */
509	        while (li > 0 && (line[li - 1] == '\r' || line[li - 1] == '\n'))
510	          {
511	            line[--li] = '\0';
512	          }
513	
514	        if (li == 0)
515	          {
516	            break;  /* blank line: end of headers */
517	          }
518	
519	        if (strstr(line, "101") != NULL && !got101)
520	          {
521	            got101 = 1;
522	          }
523	
524	        printf("[xiaozhi] <<< %s\n", line);
525	      }
526	
527	    if (!got101)
528	      {
529	        printf("[xiaozhi] ws upgrade failed (no 101)\n");
530	        return -EIO;
531	      }
532	  }
533	
534	  ws->connected = true;
535	  printf("[xiaozhi] WebSocket connected & upgraded\n");
536	  return 0;
537	}
