539	int xiaozhi_ws_send_text(struct xiaozhi_ws_s *ws, const char *data,
540	                         size_t len)
541	{
542	  if (!ws->connected)
543	    {
544	      return -ENOTCONN;
545	    }
546	
547	  return ws_send_frame(ws, WS_OPCODE_TEXT, (const uint8_t *)data, len);
548	}
