550	int xiaozhi_ws_send_binary(struct xiaozhi_ws_s *ws,
551	                           const uint8_t *data, size_t len)
552	{
553	  if (!ws->connected)
554	    {
555	      return -ENOTCONN;
556	    }
557	
558	  return ws_send_frame(ws, WS_OPCODE_BINARY, data, len);
