560	
561	int xiaozhi_ws_recv(struct xiaozhi_ws_s *ws, const uint8_t **payload,
562	                    size_t *plen, bool *is_binary)
563	{
564	  uint8_t hdr[2];
565	  uint8_t mask[4];
566	  uint8_t opcode;
567	  bool masked;
568	  uint64_t plen64;
569	  int ret;
570	
571	  if (!ws->connected)
572	    {
573	      return -ENOTCONN;
574	    }
575	
576	  /* Read the first 2 bytes of the frame header. */
577	  ret = ws_tls_read_all(ws, hdr, 2);
578	  if (ret != 0)
579	    {
580	      return ret;
581	    }
582	
583	  opcode = hdr[0] & 0x0f;
584	  masked = (hdr[1] & WS_MASK_BIT) != 0;
585	  plen64 = hdr[1] & 0x7f;
586	
587	  if (plen64 == 126)
588	    {
589	      uint8_t ext[2];
590	      ret = ws_tls_read_all(ws, ext, 2);
591	      if (ret != 0)
592	        {
593	          return ret;
594	        }
595	
596	      plen64 = ((uint64_t)ext[0] << 8) | ext[1];
597	    }
598	  else if (plen64 == 127)
599	    {
600	      uint8_t ext[8];
601	      ret = ws_tls_read_all(ws, ext, 8);
602	      if (ret != 0)
603	        {
604	          return ret;
605	        }
606	
607	      plen64 = 0;
608	      for (int i = 0; i < 8; i++)
609	        {
610	          plen64 = (plen64 << 8) | ext[i];
611	        }
612	    }
613	
614	  if (masked)
615	    {
616	      ret = ws_tls_read_all(ws, mask, 4);
617	      if (ret != 0)
618	        {
619	          return ret;
620	        }
621	    }
622	
623	  if (plen64 > ws->rxbuf_cap)
624	    {
625	      printf("[xiaozhi] frame too large: %llu\n",
626	             (unsigned long long)plen64);
627	      return -EMSGSIZE;
628	    }
629	
630	  /* Read the payload. */
631	  if (plen64 > 0)
632	    {
633	      ret = ws_tls_read_all(ws, ws->rxbuf, plen64);
634	      if (ret != 0)
635	        {
636	          return ret;
637	        }
638	
639	      if (masked)
640	        {
641	          for (uint64_t i = 0; i < plen64; i++)
642	            {
643	              ws->rxbuf[i] ^= mask[i & 3];
644	            }
645	        }
646	    }
647	
648	  /* Handle control frames transparently. */
649	  if (opcode == WS_OPCODE_CLOSE)
650	    {
651	      printf("[xiaozhi] server sent close frame\n");
652	      ws->connected = false;
653	      return -ECONNRESET;
654	    }
655	
656	  if (opcode == WS_OPCODE_PING)
657	    {
658	      /* Echo as pong. */
659	      ws_send_frame(ws, WS_OPCODE_PONG, ws->rxbuf, plen64);
660	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
661	    }
662	
663	  if (opcode == WS_OPCODE_PONG)
664	    {
665	      /* Ignore. */
666	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
667	    }
668	
669	  /* Text or binary. */
670	  *payload    = ws->rxbuf;
671	  *plen       = plen64;
672	  *is_binary  = (opcode == WS_OPCODE_BINARY);
673	  return 0;
674	}
675	
676	void xiaozhi_ws_close(struct xiaozhi_ws_s *ws)
677	{
678	  if (ws->connected)
679	    {
680	      uint8_t close_frame[] = { 0x88, 0x00 };
681	      ws_tls_write_all(ws, close_frame, 2);
682	    }
683	
684	  mbedtls_ssl_close_notify(&ws->ssl);
685	  mbedtls_ssl_free(&ws->ssl);
686	  mbedtls_ssl_config_free(&ws->conf);
687	  mbedtls_ctr_drbg_free(&ws->ctr_drbg);
688	  mbedtls_entropy_free(&ws->entropy);
689	
690	  if (ws->fd >= 0)
691	    {
692	      close(ws->fd);
693	      ws->fd = -1;
694	    }
695	
696	  if (ws->rxbuf)
697	    {
698	      free(ws->rxbuf);
699	      ws->rxbuf = NULL;
700	    }
701	
702	  ws->connected = false;
703	}
