1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_main.c
3	 *
4	 * Xiaozhi AI Voice App — Phase 2 entry point.
5	 *
6	 * Full dialog: OTA -> wss connect -> hello -> listen start -> mic capture
7	 * (Opus uplink) -> listen stop -> receive stt/tts -> TTS Opus playback.
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 ****************************************************************************/
11	
12	#include <nuttx/config.h>
13	
14	#include <stdio.h>
15	#include <string.h>
16	#include <stdlib.h>
17	#include <unistd.h>
18	#include <pthread.h>
19	#include <semaphore.h>
20	
21	#include <netutils/cJSON.h>
22	
23	#include "xiaozhi_ota.h"
24	#include "xiaozhi_ws.h"
25	#include "xiaozhi_audio.h"
26	#include "xiaozhi_mcp.h"
27	
28	/****************************************************************************
29	 * Pre-processor Definitions
30	 ****************************************************************************/
31	
32	#define XIAOZHI_MAC_DEFAULT "6b:48:a8:95:7d:e1"
33	#define XZ_OPUS_MAX        400
34	#define XZ_DIALOG_SECONDS  4      /* capture duration per turn */
35	
36	/****************************************************************************
37	 * Private Types
38	 ****************************************************************************/
39	
40	struct xiaozhi_app_s
41	{
42	  struct xiaozhi_ws_s    ws;
43	  struct xiaozhi_audio_s audio;
44	  char session_id[16];
45	  bool ws_connected;
46	  bool got_stt;
47	  bool tts_playing;
48	  int  tts_sentences;
49	};
50	
51	/* Context shared with the uplink worker thread. */
52	struct uplink_ctx_s
53	{
54	  struct xiaozhi_app_s *app;
55	  int seconds;
56	};
57	
58	/****************************************************************************
59	 * Private Data
60	 ****************************************************************************/
61	
62	static struct xiaozhi_app_s g_app;
63	
64	/****************************************************************************
65	 * Private Functions
66	 ****************************************************************************/
67	
68	/* Send a JSON text frame built with cJSON. */
69	static int send_json(struct xiaozhi_app_s *app, cJSON *root)
70	{
71	  char *json = cJSON_PrintUnformatted(root);
72	  if (json == NULL)
73	    {
74	      return -ENOMEM;
75	    }
76	
77	  int ret = xiaozhi_ws_send_text(&app->ws, json, strlen(json));
78	  free(json);
79	  return ret;
80	}
81	
82	/* Uplink worker: capture Opus frames and send as binary frames for the
83	 * given number of seconds.
84	 */
85	static void *uplink_worker(void *arg)
86	{
87	  struct uplink_ctx_s *uc = arg;
88	  struct xiaozhi_app_s *app = uc->app;
89	  uint8_t frame[XZ_OPUS_MAX];
90	  int frames = 0;
91	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
92	
93	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
94	         target_frames, uc->seconds);
95	
96	  while (frames < target_frames && app->ws_connected)
97	    {
98	      ssize_t n = xiaozhi_audio_read_opus(&app->audio, frame, sizeof(frame));
99	      if (n < 0)
100	        {
101	          printf("[xiaozhi] uplink read err: %zd\n", n);
102	          break;
103	        }
104	
105	      if (n > 0)
106	        {
107	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
108	          if (ret != 0)
109	            {
110	              printf("[xiaozhi] uplink send err: %d\n", ret);
111	              break;
112	            }
113	
114	          frames++;
115	        }
116	    }
117	
118	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
119	  return NULL;
120	}
121	
122	/* Receive worker: parse server messages and feed TTS audio to the player.
123	 * Runs until ws is closed or a stop condition.
124	 */
125	static void recv_loop(struct xiaozhi_app_s *app, int max_ms)
126	{
127	  int waited = 0;
128	
129	  while (app->ws_connected && waited < max_ms)
130	    {
131	      const uint8_t *payload;
132	      size_t plen;
133	      bool is_binary;
134	      int ret;
135	
136	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
137	      if (ret != 0)
138	        {
139	          app->ws_connected = false;
140	          break;
141	        }
142	
143	      if (is_binary)
144	        {
145	          /* Server TTS Opus frame -> feed to player. */
146	          if (app->tts_playing)
147	            {
148	              xiaozhi_audio_write_opus(&app->audio, payload, plen);
149	            }
150	
151	          waited += 60;
152	          continue;
153	        }
154	
155	      /* Text frame: parse JSON. */
156	      {
157	        char *json = malloc(plen + 1);
158	        if (json == NULL)
159	          {
160	            continue;
161	          }
162	
163	        memcpy(json, payload, plen);
164	        json[plen] = '\0';
165	
166	        cJSON *root = cJSON_Parse(json);
167	        if (root != NULL)
168	          {
169	            cJSON *type = cJSON_GetObjectItem(root, "type");
170	            const char *tstr = cJSON_IsString(type) ?
171	              type->valuestring : "";
172	
173	            if (strcmp(tstr, "stt") == 0)
174	              {
175	                cJSON *text = cJSON_GetObjectItem(root, "text");
176	                printf("[xiaozhi] <<< STT: \"%s\"\n",
177	                       text ? text->valuestring : "?");
178	                app->got_stt = true;
179	              }
180	            else if (strcmp(tstr, "llm") == 0)
181	              {
182	                cJSON *text = cJSON_GetObjectItem(root, "text");
183	                printf("[xiaozhi] <<< LLM: \"%s\" (%s)\n",
184	                       text ? text->valuestring : "?",
185	                       cJSON_IsString(cJSON_GetObjectItem(root, "emotion")) ?
186	                       cJSON_GetObjectItem(root, "emotion")->valuestring :
187	                       "-");
188	              }
189	            else if (strcmp(tstr, "mcp") == 0)
190	              {
191	                cJSON *payload = cJSON_GetObjectItem(root, "payload");
192	                if (cJSON_IsObject(payload))
193	                  {
194	                    xiaozhi_mcp_handle_message(&app->ws,
195	                                               app->session_id, payload);
196	                  }
197	              }
198	            else if (strcmp(tstr, "tts") == 0)
199	              {
200	                cJSON *state = cJSON_GetObjectItem(root, "state");
201	                const char *sstr = cJSON_IsString(state) ?
202	                  state->valuestring : "";
203	
204	                if (strcmp(sstr, "start") == 0)
205	                  {
206	                    app->tts_playing = true;
207	                    xiaozhi_audio_start_playback(&app->audio);
208	                    printf("[xiaozhi] <<< TTS start\n");
209	                  }
210	                else if (strcmp(sstr, "stop") == 0)
211	                  {
212	                    app->tts_playing = false;
213	                    printf("[xiaozhi] <<< TTS stop\n");
214	                    xiaozhi_audio_stop_playback(&app->audio);
215	                    break;   /* end of this turn */
216	                  }
217	                else if (strcmp(sstr, "sentence_start") == 0)
218	                  {
219	                    cJSON *text = cJSON_GetObjectItem(root, "text");
220	                    printf("[xiaozhi] <<< TTS: \"%s\"\n",
221	                           text ? text->valuestring : "?");
222	                    app->tts_sentences++;
223	                  }
224	              }
225	            else if (strcmp(tstr, "goodbye") == 0)
226	              {
227	                printf("[xiaozhi] <<< goodbye\n");
228	                app->ws_connected = false;
229	                cJSON_Delete(root);
230	                free(json);
231	                break;
232	              }
233	            else if (strcmp(tstr, "hello") == 0)
234	              {
235	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
236	                if (cJSON_IsString(sid))
237	                  {
238	                    strncpy(app->session_id, sid->valuestring,
239	                            sizeof(app->session_id) - 1);
240	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
241	                           app->session_id);
242	                  }
243	              }
244	            else
245	              {
246	                printf("[xiaozhi] <<< %s\n", tstr);
247	              }
248	
249	            cJSON_Delete(root);
250	          }
251	        else
252	          {
253	            printf("[xiaozhi] <<< (parse err) %.*s\n",
254	                   (int)plen, (const char *)payload);
255	          }
256	
257	        free(json);
258	      }
259	
260	      waited += 60;
261	    }
262	}
263	
264	/****************************************************************************
265	 * Public Functions
266	 ****************************************************************************/
267	
268	int main(int argc, FAR char *argv[])
269	{
270	  struct xiaozhi_ota_config_s ota;
271	  const char *mac = XIAOZHI_MAC_DEFAULT;
272	  char client_id[40];
273	  int ret;
274	  struct uplink_ctx_s uc;
275	
276	  memset(&g_app, 0, sizeof(g_app));
277	
278	  printf("[xiaozhi] === Phase 2: full dialog ===\n");
279	
280	  snprintf(client_id, sizeof(client_id),
281	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
282	
283	  /* Init audio subsystem. */
284	  ret = xiaozhi_audio_init(&g_app.audio);
285	  if (ret != 0)
286	    {
287	      printf("[xiaozhi] audio init failed: %d\n", ret);
288	      return 1;
289	    }
290	
291	  /* Step 1: OTA. */
292	  printf("[xiaozhi] step 1: OTA\n");
293	  ret = xiaozhi_ota_fetch(mac, &ota);
294	  if (ret != 0)
295	    {
296	      printf("[xiaozhi] OTA failed: %d\n", ret);
297	      return 1;
298	    }
299	
300	  /* Step 2: wss connect + hello. */
301	  printf("[xiaozhi] step 2: wss connect\n");
302	  ret = xiaozhi_ws_connect(&g_app.ws, ota.ws_url, ota.ws_token, mac,
303	                           client_id);
304	  if (ret != 0)
305	    {
306	      printf("[xiaozhi] ws connect failed: %d\n", ret);
307	      return 1;
308	    }
309	
310	  g_app.ws_connected = true;
311	
312	  /* Wait for hello response to get session_id. */
313	  printf("[xiaozhi] step 3: wait hello\n");
314	  recv_loop(&g_app, 5000);   /* up to 5s for hello */
315	  if (g_app.session_id[0] == '\0')
316	    {
317	      printf("[xiaozhi] no session_id, abort\n");
318	      goto out;
319	    }
320	
321	  /* Announce device capabilities (notably MCP) to the cloud with a device
322	   * hello. The cloud starts an MCP session only after seeing features.mcp.
323	   */
324	  {
325	    cJSON *hello       = cJSON_CreateObject();
326	    cJSON *features    = cJSON_CreateObject();
327	    cJSON *audio_params = cJSON_CreateObject();
328	
329	    cJSON_AddStringToObject(hello, "type", "hello");
330	    cJSON_AddNumberToObject(hello, "version", 1);
331	    cJSON_AddStringToObject(hello, "transport", "websocket");
332	    cJSON_AddItemToObject(hello, "features", features);
333	    xiaozhi_mcp_add_features(features);
334	    cJSON_AddItemToObject(hello, "audio_params", audio_params);
335	    cJSON_AddStringToObject(audio_params, "format", "opus");
336	    cJSON_AddNumberToObject(audio_params, "sample_rate", 16000);
337	    cJSON_AddNumberToObject(audio_params, "channels", 1);
338	
339	    send_json(&g_app, hello);
340	    cJSON_Delete(hello);
341	    printf("[xiaozhi] >>> hello (features.mcp=true)\n");
342	  }
343	
344	  /* Step 4: listen start + capture + listen stop. */
345	  printf("[xiaozhi] step 4: listen start + capture\n");
346	  {
347	    cJSON *hello = cJSON_CreateObject();
348	    cJSON_AddStringToObject(hello, "session_id", g_app.session_id);
349	    cJSON_AddStringToObject(hello, "type", "listen");
350	    cJSON_AddStringToObject(hello, "state", "start");
351	    cJSON_AddStringToObject(hello, "mode", "manual");
352	    send_json(&g_app, hello);
353	    cJSON_Delete(hello);
354	    printf("[xiaozhi] >>> listen start\n");
355	  }
356	
357	  /* Start capture and run uplink worker for N seconds. */
358	  ret = xiaozhi_audio_start_capture(&g_app.audio);
359	  if (ret != 0)
360	    {
361	      printf("[xiaozhi] capture start failed: %d\n", ret);
362	      goto out;
363	    }
364	
365	  /* Drain any incoming binary/text while capturing by spawning uplink in
366	   * a thread and looping recv here too. Simplest: run uplink synchronously
367	   * (block on capture), the server tolerates a gap before listen stop.
368	   */
369	  uc.app = &g_app;
370	  uc.seconds = XZ_DIALOG_SECONDS;
371	  uplink_worker(&uc);
372	
373	  xiaozhi_audio_stop_capture(&g_app.audio);
374	
375	  /* listen stop. */
376	  {
377	    cJSON *stop = cJSON_CreateObject();
378	    cJSON_AddStringToObject(stop, "session_id", g_app.session_id);
379	    cJSON_AddStringToObject(stop, "type", "listen");
380	    cJSON_AddStringToObject(stop, "state", "stop");
381	    send_json(&g_app, stop);
382	    cJSON_Delete(stop);
383	    printf("[xiaozhi] >>> listen stop\n");
384	  }
385	
386	  /* Step 5: receive stt + tts + playback (up to 20s). */
387	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
388	  recv_loop(&g_app, 20000);
389	
390	out:
391	  if (g_app.tts_playing)
392	    {
393	      xiaozhi_audio_stop_playback(&g_app.audio);
394	    }
395	
396	  xiaozhi_audio_deinit(&g_app.audio);
397	  xiaozhi_ws_close(&g_app.ws);
398	
399	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
400	         g_app.got_stt ? "yes" : "no", g_app.tts_sentences);
401	  return 0;
402	}
