/****************************************************************************
 * apps/examples/xiaozhi_voice/xiaozhi_mcp.c
 *
 * Minimal MCP (Model Context Protocol) server side for the xiaozhi voice
 * app. See xiaozhi_mcp.h for an overview.
 *
 * The cloud sends MCP JSON-RPC requests inside WebSocket text frames:
 *
 *   { "type": "mcp", "payload": <jsonrpc request> }
 *
 * We handle three methods:
 *   - initialize      -> serverInfo + protocolVersion + capabilities
 *   - tools/list      -> list of tool descriptors
 *   - tools/call      -> dispatch by name to a built-in handler
 *
 * Responses are sent back as mcp text frames:
 *
 *   { "type":"mcp", "session_id":<sid>, "payload": <jsonrpc response> }
 *
 * Built-in tools:
 *   - self.app.start_lvgldemo : launch the on-device LVGL demo (detached)
 *   - calculator             : evaluate a math expression (shunting-yard)
 *
 * The calculator mirrors the reference Python MCP server in
 * mcp-calculator-main/calculator.py, which exposes a single tool that
 * evaluates a Python expression. There is no Python on the device, so the
 * expression is parsed by a small recursive-descent / shunting-yard
 * evaluator supporting + - * / %, unary +/-, parentheses, and the common
 * math functions (sqrt, sin, cos, tan, exp, log, pow, abs, floor, ceil),
 * with constants pi and e.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <math.h>
#include <pthread.h>
#include <errno.h>

#include <netutils/cJSON.h>

#include "xiaozhi_mcp.h"

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* A function callable from a calculator expression. */
struct calc_fn_s
{
  const char *name;
  int  argc;            /* 1 or 2 */
  double (*fn1)(double);
  double (*fn2)(double, double);
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Math functions exposed to the calculator expression. The entry order does
 * not matter; lookup is linear (the list is short).
 */
static const struct calc_fn_s g_calc_fns[] =
{
  { "sqrt",  1, sqrt,  NULL   },
  { "sin",   1, sin,   NULL   },
  { "cos",   1, cos,   NULL   },
  { "tan",   1, tan,   NULL   },
  { "asin",  1, asin,  NULL   },
  { "acos",  1, acos,  NULL   },
  { "atan",  1, atan,  NULL   },
  { "exp",   1, exp,   NULL   },
  { "log",   1, log,   NULL   },   /* natural log */
  { "log10", 1, log10, NULL   },
  { "floor", 1, floor, NULL   },
  { "ceil",  1, ceil,  NULL   },
  { "abs",   1, fabs,  NULL   },
  { "pow",   2, NULL,  pow    },
  { "atan2", 2, NULL,  atan2  },
  { "max",   2, NULL,  fmax   },
  { "min",   2, NULL,  fmin   },
};

#define CALC_FN_COUNT (sizeof(g_calc_fns) / sizeof(g_calc_fns[0]))

/****************************************************************************
 * Private: calculator expression evaluator
 ****************************************************************************/

/* Token kinds for the calculator lexer. */
enum tok_kind_e
{
  TOK_END,
  TOK_NUM,
  TOK_OP,
  TOK_LPAREN,
  TOK_RPAREN,
  TOK_COMMA,
  TOK_IDENT,
};

struct tok_s
{
  enum tok_kind_e kind;
  double num;        /* for TOK_NUM */
  char op;          /* for TOK_OP  */
  char ident[16];   /* for TOK_IDENT */
};

/* Evaluator state: a cursor over the input string plus the lookahead token. */
struct calc_s
{
  const char *p;
  struct tok_s cur;
  bool error;
  const char *errmsg;
};

/* Forward declarations for the recursive-descent parser (precedence
 * climbing). */
static double parse_expr(struct calc_s *c);
static double parse_term(struct calc_s *c);
static double parse_factor(struct calc_s *c);
static double parse_primary(struct calc_s *c);

static void calc_error(struct calc_s *c, const char *msg)
{
  if (!c->error)
    {
      c->error   = true;
      c->errmsg  = msg;
    }
}

/* Lex one token from c->p into c->cur. */
static void calc_next(struct calc_s *c)
{
  /* Skip whitespace. */
  while (*c->p == ' ' || *c->p == '\t' || *c->p == '\r' || *c->p == '\n')
    {
      c->p++;
    }

  if (*c->p == '\0')
    {
      c->cur.kind = TOK_END;
      return;
    }

  /* Number: digits, optional decimal point, optional exponent. */
  if ((*c->p >= '0' && *c->p <= '9') || *c->p == '.')
    {
      char *end;
      double v = strtod(c->p, &end);
      if (end == c->p)
        {
          calc_error(c, "invalid number");
          c->cur.kind = TOK_END;
          return;
        }

      c->p        = end;
      c->cur.kind = TOK_NUM;
      c->cur.num  = v;
      return;
    }

  /* Identifier: function name or constant (pi / e). */
  if ((*c->p >= 'a' && *c->p <= 'z') || (*c->p >= 'A' && *c->p <= 'Z') ||
      *c->p == '_')
    {
      size_t n = 0;
      while (n + 1 < sizeof(c->cur.ident) &&
             ((*c->p >= 'a' && *c->p <= 'z') ||
              (*c->p >= 'A' && *c->p <= 'Z') ||
              (*c->p >= '0' && *c->p <= '9') ||
              *c->p == '_'))
        {
          c->cur.ident[n++] = *c->p++;
        }

      c->cur.ident[n] = '\0';
      c->cur.kind     = TOK_IDENT;
      return;
    }

  /* Single-character tokens. */
  switch (*c->p)
    {
      case '+':
      case '-':
      case '*':
      case '/':
      case '%':
      case '^':
        c->cur.kind = TOK_OP;
        c->cur.op   = *c->p++;
        return;

      case '(':
        c->cur.kind = TOK_LPAREN;
        c->p++;
        return;

      case ')':
        c->cur.kind = TOK_RPAREN;
        c->p++;
        return;

      case ',':
        c->cur.kind = TOK_COMMA;
        c->p++;
        return;

      default:
        calc_error(c, "unexpected character");
        c->cur.kind = TOK_END;
        c->p++;
        return;
    }
}

/* Look up a function by name. Returns NULL if not found. */
static const struct calc_fn_s *calc_lookup_fn(const char *name)
{
  for (size_t i = 0; i < CALC_FN_COUNT; i++)
    {
      if (strcmp(g_calc_fns[i].name, name) == 0)
        {
          return &g_calc_fns[i];
        }
    }

  return NULL;
}

/* primary := number
 *         | ident ('(' expr (',' expr)? ')')?     # constant or call
 *         | '(' expr ')'
 *         | ('+' | '-') primary                    # unary
 */
static double parse_primary(struct calc_s *c)
{
  if (c->error)
    {
      return 0.0;
    }

  if (c->cur.kind == TOK_NUM)
    {
      double v = c->cur.num;
      calc_next(c);
      return v;
    }

  if (c->cur.kind == TOK_OP && (c->cur.op == '+' || c->cur.op == '-'))
    {
      char op = c->cur.op;
      calc_next(c);
      double v = parse_primary(c);
      return (op == '-') ? -v : v;
    }

  if (c->cur.kind == TOK_LPAREN)
    {
      calc_next(c);
      double v = parse_expr(c);
      if (c->cur.kind != TOK_RPAREN)
        {
          calc_error(c, "missing ')'");
          return 0.0;
        }

      calc_next(c);
      return v;
    }

  if (c->cur.kind == TOK_IDENT)
    {
      char name[16];
      strlcpy(name, c->cur.ident, sizeof(name));
      calc_next(c);

      /* Function call: ident '(' expr [',' expr] ')'. */
      if (c->cur.kind == TOK_LPAREN)
        {
          calc_next(c);
          double a = parse_expr(c);
          double b = 0.0;

          if (c->cur.kind == TOK_COMMA)
            {
              calc_next(c);
              b = parse_expr(c);
            }

          if (c->cur.kind != TOK_RPAREN)
            {
              calc_error(c, "missing ')' in call");
              return 0.0;
            }

          calc_next(c);

          const struct calc_fn_s *f = calc_lookup_fn(name);
          if (f == NULL)
            {
              calc_error(c, "unknown function");
              return 0.0;
            }

          if (f->argc == 1)
            {
              if (f->fn1 == NULL)
                {
                  calc_error(c, "bad function");
                  return 0.0;
                }

              return f->fn1(a);
            }
          else
            {
              if (f->fn2 == NULL)
                {
                  calc_error(c, "bad function");
                  return 0.0;
                }

              return f->fn2(a, b);
            }
        }

      /* Constant. */
      if (strcmp(name, "pi") == 0)
        {
          return M_PI;
        }

      if (strcmp(name, "e") == 0)
        {
          return M_E;
        }

      calc_error(c, "unknown identifier");
      return 0.0;
    }

  calc_error(c, "unexpected token");
  return 0.0;
}

/* factor := primary ('^' factor)?   # right-associative power */
static double parse_factor(struct calc_s *c)
{
  double base = parse_primary(c);
  if (c->error)
    {
      return 0.0;
    }

  if (c->cur.kind == TOK_OP && c->cur.op == '^')
    {
      calc_next(c);
      double exp = parse_factor(c);   /* right-assoc */
      if (c->error)
        {
          return 0.0;
        }

      return pow(base, exp);
    }

  return base;
}

/* term := factor (('*' | '/' | '%') factor)* */
static double parse_term(struct calc_s *c)
{
  double v = parse_factor(c);
  while (!c->error &&
         c->cur.kind == TOK_OP &&
         (c->cur.op == '*' || c->cur.op == '/' || c->cur.op == '%'))
    {
      char op = c->cur.op;
      calc_next(c);
      double rhs = parse_factor(c);
      if (c->error)
        {
          return 0.0;
        }

      if (op == '*')
        {
          v *= rhs;
        }
      else if (op == '/')
        {
          if (rhs == 0.0)
            {
              calc_error(c, "division by zero");
              return 0.0;
            }

          v /= rhs;
        }
      else  /* '%' */
        {
          if (rhs == 0.0)
            {
              calc_error(c, "modulo by zero");
              return 0.0;
            }

          v = fmod(v, rhs);
        }
    }

  return v;
}

/* expr := term (('+' | '-') term)* */
static double parse_expr(struct calc_s *c)
{
  double v = parse_term(c);
  while (!c->error &&
         c->cur.kind == TOK_OP &&
         (c->cur.op == '+' || c->cur.op == '-'))
    {
      char op = c->cur.op;
      calc_next(c);
      double rhs = parse_term(c);
      if (c->error)
        {
          return 0.0;
        }

      v = (op == '+') ? v + rhs : v - rhs;
    }

  return v;
}

/* Evaluate a calculator expression string. On success returns 0 and writes
 * the result to *out. On failure returns -1 and sets *errbuf to a short
 * reason (static string). */
static int calc_evaluate(const char *expr, double *out, const char **errbuf)
{
  struct calc_s c;
  c.p      = expr;
  c.error  = false;
  c.errmsg = NULL;

  calc_next(&c);
  double v = parse_expr(&c);
  if (c.error)
    {
      if (errbuf != NULL)
        {
          *errbuf = c.errmsg ? c.errmsg : "syntax error";
        }

      return -1;
    }

  if (c.cur.kind != TOK_END)
    {
      if (errbuf != NULL)
        {
          *errbuf = "unexpected trailing input";
        }

      return -1;
    }

  if (isinf(v) || isnan(v))
    {
      if (errbuf != NULL)
        {
          *errbuf = "result is not finite";
        }

      return -1;
    }

  *out = v;
  return 0;
}

/****************************************************************************
 * Private: MCP framing helpers
 ****************************************************************************/

/* Build the JSON-RPC response envelope and send it as an mcp text frame. */
static int send_mcp_frame(struct xiaozhi_ws_s *ws, const char *session_id,
                          cJSON *result)
{
  int ret;
  char *json;

  cJSON *frame   = cJSON_CreateObject();
  cJSON *payload = cJSON_CreateObject();

  cJSON_AddStringToObject(frame, "type", "mcp");
  cJSON_AddStringToObject(frame, "session_id", session_id);
  cJSON_AddItemToObject(frame, "payload", payload);

  /* Copy the result fields into the payload. The caller-built result is a
   * JSON-RPC response object; adopt it directly so we do not need to know
   * its keys. */
  cJSON *item = result->child;
  while (item != NULL)
    {
      cJSON *next = item->next;
      cJSON_DeleteItemFromObject(payload, item->string);
      cJSON_AddItemToObject(payload, item->string, cJSON_DetachItemViaPointer(result, item));
      item = next;
    }

  json = cJSON_PrintUnformatted(frame);
  if (json != NULL)
    {
      ret = xiaozhi_ws_send_text(ws, json, strlen(json));
      free(json);
    }
  else
    {
      ret = -ENOMEM;
    }

  cJSON_Delete(frame);
  cJSON_Delete(result);
  return ret;
}

/* Build a JSON-RPC result object for the given request id. */
static cJSON *reply_result(cJSON *id)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
  return resp;
}

/* Build a JSON-RPC error object for the given request id and code/message. */
static cJSON *reply_error(cJSON *id, int code, const char *message)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON *err  = cJSON_CreateObject();

  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "error", err);
  cJSON_AddNumberToObject(err, "code", code);
  cJSON_AddStringToObject(err, "message", message);
  return resp;
}

/* Build a text content block, the shape MCP tools/call results use. */
static cJSON *make_text_result(const char *text)
{
  cJSON *content = cJSON_CreateArray();
  cJSON *item    = cJSON_CreateObject();

  cJSON_AddItemToArray(content, item);
  cJSON_AddStringToObject(item, "type", "text");
  cJSON_AddStringToObject(item, "text", text);
  return content;
}

/****************************************************************************
 * Private: tool handlers
 ****************************************************************************/

/* Detached worker for start_lvgldemo: the LVGL demo is a long-running GUI
 * process, so we launch it asynchronously and let the worker block on it.
 */
static void *lvgldemo_worker(void *arg)
{
  int ret;

  printf("[xiaozhi] mcp: launching lvgldemo\n");
  ret = system("lvgldemo");
  printf("[xiaozhi] mcp: lvgldemo exited (rc=%d)\n", ret);
  return NULL;
}

/* Handle a tools/call request. Returns a JSON-RPC response object (either
 * a result with content, or an error). Caller frees it. */
static cJSON *handle_tools_call(cJSON *params)
{
  cJSON *name = cJSON_GetObjectItem(params, "name");
  cJSON *args = cJSON_GetObjectItem(params, "arguments");
  const char *namestr = cJSON_IsString(name) ? name->valuestring : NULL;

  if (namestr == NULL)
    {
      return reply_error(NULL, -32602, "Missing tool name");
    }

  if (!cJSON_IsObject(args))
    {
      args = NULL;   /* arguments are optional for some tools */
    }

  /* self.app.start_lvgldemo: launch the LVGL demo on a detached thread. */
  if (strcmp(namestr, XIAOZHI_MCP_TOOL_LVGLDEMO) == 0)
    {
      pthread_t tid;
      pthread_attr_t attr;
      int ret;

      pthread_attr_init(&attr);
      pthread_attr_setstacksize(&attr, XIAOZHI_MCP_WORKER_STACK);
      pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

      ret = pthread_create(&tid, &attr, lvgldemo_worker, NULL);
      pthread_attr_destroy(&attr);

      if (ret != 0)
        {
          char msg[64];
          snprintf(msg, sizeof(msg), "Failed to launch lvgldemo: %d", ret);
          return reply_error(NULL, -32603, msg);
        }

      return reply_result(NULL);   /* id filled in by caller */
    }

  /* calculator: evaluate a math expression. */
  if (strcmp(namestr, XIAOZHI_MCP_TOOL_CALCULATOR) == 0)
    {
      cJSON *expr = args ? cJSON_GetObjectItem(args, "python_expression") : NULL;
      if (!cJSON_IsString(expr))
        {
          return reply_error(NULL, -32602, "Missing python_expression");
        }

      double result;
      const char *err = NULL;
      if (calc_evaluate(expr->valuestring, &result, &err) != 0)
        {
          /* On a parse/eval error, MCP convention is to return an
           * isError result rather than a JSON-RPC error, so the LLM can
           * see the message and retry. */
          cJSON *resp = reply_result(NULL);
          cJSON *errtext = make_text_result(err ? err : "syntax error");
          cJSON *resultobj = cJSON_GetObjectItem(resp, "result");
          cJSON_AddItemToObject(resultobj, "content", errtext);
          cJSON_AddBoolToObject(resultobj, "isError", true);
          return resp;
        }

      /* Success: return the numeric result as a text content block. */
      char buf[64];
      snprintf(buf, sizeof(buf), "%.12g", result);

      cJSON *resp     = reply_result(NULL);
      cJSON *resultobj = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(resultobj, "content", make_text_result(buf));
      cJSON_AddBoolToObject(resultobj, "isError", false);
      return resp;
    }

  return reply_error(NULL, -32601, "Unknown tool");
}

/* Build one tool descriptor for tools/list. */
static cJSON *make_tool_descriptor(const char *name, const char *desc,
                                   cJSON *schema)
{
  cJSON *tool = cJSON_CreateObject();
  cJSON_AddStringToObject(tool, "name", name);
  cJSON_AddStringToObject(tool, "description", desc);
  cJSON_AddItemToObject(tool, "inputSchema", schema);
  return tool;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void xiaozhi_mcp_add_features(cJSON *features)
{
  if (features == NULL)
    {
      return;
    }

  cJSON_AddBoolToObject(features, "mcp", true);
}

void xiaozhi_mcp_handle_message(struct xiaozhi_ws_s *ws,
                                const char *session_id,
                                cJSON *payload)
{
  cJSON *method = cJSON_GetObjectItem(payload, "method");
  cJSON *id     = cJSON_GetObjectItem(payload, "id");
  cJSON *params = cJSON_GetObjectItem(payload, "params");
  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;

  if (mstr == NULL)
    {
      cJSON *resp = reply_error(id, -32600, "Missing method");
      send_mcp_frame(ws, session_id, resp);
      return;
    }

  printf("[xiaozhi] mcp: method=%s id=%d\n", mstr,
         cJSON_IsNumber(id) ? id->valuedouble : -1);

  if (strcmp(mstr, "initialize") == 0)
    {
      cJSON *resp     = reply_result(id);
      cJSON *result   = cJSON_GetObjectItem(resp, "result");
      cJSON *info     = cJSON_CreateObject();
      cJSON *caps     = cJSON_CreateObject();
      cJSON *toolscap = cJSON_CreateObject();

      cJSON_AddStringToObject(result, "protocolVersion",
                              XIAOZHI_MCP_PROTOCOL_VERSION);
      cJSON_AddItemToObject(result, "serverInfo", info);
      cJSON_AddStringToObject(info, "name", XIAOZHI_MCP_SERVER_NAME);
      cJSON_AddStringToObject(info, "version", XIAOZHI_MCP_SERVER_VERSION);
      cJSON_AddItemToObject(result, "capabilities", caps);
      cJSON_AddItemToObject(caps, "tools", toolscap);
      cJSON_AddBoolToObject(toolscap, "listChanged", false);

      send_mcp_frame(ws, session_id, resp);
      return;
    }

  if (strcmp(mstr, "tools/list") == 0)
    {
      cJSON *resp   = reply_result(id);
      cJSON *result = cJSON_GetObjectItem(resp, "result");
      cJSON *tools  = cJSON_CreateArray();

      /* self.app.start_lvgldemo */
      {
        cJSON *schema = cJSON_CreateObject();
        cJSON *props  = cJSON_CreateObject();
        cJSON_AddStringToObject(schema, "type", "object");
        cJSON_AddItemToObject(schema, "properties", props);
        cJSON_AddStringToObject(schema, "description",
          "Start the LVGL demo application on the device.");
        cJSON_AddItemToArray(tools,
          make_tool_descriptor(XIAOZHI_MCP_TOOL_LVGLDEMO,
            "Start the LVGL demo application on the device.",
            schema));
      }

      /* calculator */
      {
        cJSON *schema = cJSON_CreateObject();
        cJSON *props  = cJSON_CreateObject();
        cJSON *expr   = cJSON_CreateObject();
        cJSON *reqd   = cJSON_CreateArray();

        cJSON_AddStringToObject(schema, "type", "object");
        cJSON_AddItemToObject(schema, "properties", props);
        cJSON_AddItemToObject(props, "python_expression", expr);
        cJSON_AddStringToObject(expr, "type", "string");
        cJSON_AddStringToObject(expr, "description",
          "A math expression to evaluate, e.g. '2+3*4', 'sqrt(2)', "
          "'sin(pi/2)', 'pow(2,10)'. Supports + - * / % ^, parentheses, "
          "and functions sqrt/sin/cos/tan/exp/log/log10/floor/ceil/abs/pow/"
          "atan2/max/min plus constants pi and e.");
        cJSON_AddItemToObject(schema, "required", reqd);
        cJSON_AddItemToArray(reqd, cJSON_CreateString("python_expression"));

        cJSON_AddItemToArray(tools,
          make_tool_descriptor(XIAOZHI_MCP_TOOL_CALCULATOR,
            "Evaluate a mathematical expression and return the result. "
            "Use this for any arithmetic calculation requested by the "
            "user.",
            schema));
      }

      cJSON_AddItemToObject(result, "tools", tools);
      send_mcp_frame(ws, session_id, resp);
      return;
    }

  if (strcmp(mstr, "tools/call") == 0)
    {
      cJSON *resp = handle_tools_call(params ? params : cJSON_CreateObject());

      /* handle_tools_call does not know the request id; fill it in here. */
      cJSON *repid = cJSON_GetObjectItem(resp, "id");
      if (repid == NULL)
        {
          cJSON_AddItemReferenceToObject(resp, "id", id);
        }

      send_mcp_frame(ws, session_id, resp);
      return;
    }

  /* Notifications (no id) are not answered; other methods are unsupported. */
  if (id == NULL)
    {
      return;
    }

  {
    char msg[64];
    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
    send_mcp_frame(ws, session_id, reply_error(id, -32601, msg));
  }
}

