    {"cos(0)", 1.0},
    {"pow(2,3)", 8},
    {"max(3,7)", 7},
    {"min(3,7)", 3},
    {"abs(-5)", 5},
    {"-3+5", 2},
    {"e", 2.718281828459045},
    {"2*  -  3", -6},
    {"floor(3.7)", 3},
    {"ceil(3.2)", 4},
    {"log(exp(1))", 1},
  };
