    printf("%s %-20s = %.12g  (want %.12g)\n", ok?"ok ":"BAD", cases[i].e, r, cases[i].want);
    pass += ok;
  }
  /* error cases */
  const char *errs[] = {"1/0", "2+", "foo(1)", "1.2.3", "@#$", "", "(1+2", "1 2"};
  for (int i=0;i<(int)(sizeof(errs)/sizeof(errs[0]));i++){
    double r; const char *err=NULL;
