1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_mcp.c
3	 *
4	 * Minimal MCP (Model Context Protocol) server side for the xiaozhi voice
5	 * app. See xiaozhi_mcp.h for an overview.
6	 *
7	 * The cloud sends MCP JSON-RPC requests inside WebSocket text frames:
8	 *
9	 *   { "type": "mcp", "payload": <jsonrpc request> }
10	 *
11	 * We handle three methods:
12	 *   - initialize      -> serverInfo + protocolVersion + capabilities
13	 *   - tools/list      -> list of tool descriptors
14	 *   - tools/call      -> dispatch by name to a built-in handler
15	 *
16	 * Responses are sent back as mcp text frames:
17	 *
18	 *   { "type":"mcp", "session_id":<sid>, "payload": <jsonrpc response> }
19	 *
20	 * Built-in tools:
21	 *   - calculator : evaluate a math expression (recursive-descent evaluator)
22	 *
23	 * The calculator mirrors the reference Python MCP server in
24	 * mcp-calculator-main/calculator.py, which exposes a single tool that
25	 * evaluates a Python expression. There is no Python on the device, so the
26	 * expression is parsed by a small recursive-descent / shunting-yard
27	 * evaluator supporting + - * / %, unary +/-, parentheses, and the common
28	 * math functions (sqrt, sin, cos, tan, exp, log, pow, abs, floor, ceil),
29	 * with constants pi and e.
30	 *
31	 * SPDX-License-Identifier: Apache-2.0
32	 ****************************************************************************/
33	
34	#include <nuttx/config.h>
35	
36	#include <stdio.h>
37	#include <stdlib.h>
38	#include <string.h>
39	#include <stdbool.h>
40	#include <math.h>
41	#include <errno.h>
42	
43	#include <netutils/cJSON.h>
44	
45	#include "xiaozhi_mcp.h"
46	
47	/****************************************************************************
48	 * Private Types
49	 ****************************************************************************/
50	
51	/* A function callable from a calculator expression. */
52	struct calc_fn_s
53	{
54	  const char *name;
55	  int  argc;            /* 1 or 2 */
56	  double (*fn1)(double);
57	  double (*fn2)(double, double);
58	};
59	
60	/****************************************************************************
61	 * Private Data
62	 ****************************************************************************/
63	
64	/* Math functions exposed to the calculator expression. The entry order does
65	 * not matter; lookup is linear (the list is short).
66	 */
67	static const struct calc_fn_s g_calc_fns[] =
68	{
69	  { "sqrt",  1, sqrt,  NULL   },
70	  { "sin",   1, sin,   NULL   },
71	  { "cos",   1, cos,   NULL   },
72	  { "tan",   1, tan,   NULL   },
73	  { "asin",  1, asin,  NULL   },
74	  { "acos",  1, acos,  NULL   },
75	  { "atan",  1, atan,  NULL   },
76	  { "exp",   1, exp,   NULL   },
77	  { "log",   1, log,   NULL   },   /* natural log */
78	  { "log10", 1, log10, NULL   },
79	  { "floor", 1, floor, NULL   },
80	  { "ceil",  1, ceil,  NULL   },
81	  { "abs",   1, fabs,  NULL   },
82	  { "pow",   2, NULL,  pow    },
83	  { "atan2", 2, NULL,  atan2  },
84	  { "max",   2, NULL,  fmax   },
85	  { "min",   2, NULL,  fmin   },
86	};
87	
88	#define CALC_FN_COUNT (sizeof(g_calc_fns) / sizeof(g_calc_fns[0]))
89	
90	/****************************************************************************
91	 * Private: calculator expression evaluator
92	 ****************************************************************************/
93	
94	/* Token kinds for the calculator lexer. */
95	enum tok_kind_e
96	{
97	  TOK_END,
98	  TOK_NUM,
99	  TOK_OP,
100	  TOK_LPAREN,
101	  TOK_RPAREN,
102	  TOK_COMMA,
103	  TOK_IDENT,
104	};
105	
106	struct tok_s
107	{
108	  enum tok_kind_e kind;
109	  double num;        /* for TOK_NUM */
110	  char op;          /* for TOK_OP  */
111	  char ident[16];   /* for TOK_IDENT */
112	};
113	
114	/* Evaluator state: a cursor over the input string plus the lookahead token. */
115	struct calc_s
116	{
117	  const char *p;
118	  struct tok_s cur;
119	  bool error;
120	  const char *errmsg;
121	};
122	
123	/* Forward declarations for the recursive-descent parser (precedence
124	 * climbing). */
125	static double parse_expr(struct calc_s *c);
126	static double parse_term(struct calc_s *c);
127	static double parse_factor(struct calc_s *c);
128	static double parse_primary(struct calc_s *c);
129	
130	static void calc_error(struct calc_s *c, const char *msg)
131	{
132	  if (!c->error)
133	    {
134	      c->error   = true;
135	      c->errmsg  = msg;
136	    }
137	}
138	
139	/* Lex one token from c->p into c->cur. */
140	static void calc_next(struct calc_s *c)
141	{
142	  /* Skip whitespace. */
143	  while (*c->p == ' ' || *c->p == '\t' || *c->p == '\r' || *c->p == '\n')
144	    {
145	      c->p++;
146	    }
147	
148	  if (*c->p == '\0')
149	    {
150	      c->cur.kind = TOK_END;
151	      return;
152	    }
153	
154	  /* Number: digits, optional decimal point, optional exponent. */
155	  if ((*c->p >= '0' && *c->p <= '9') || *c->p == '.')
156	    {
157	      char *end;
158	      double v = strtod(c->p, &end);
159	      if (end == c->p)
160	        {
161	          calc_error(c, "invalid number");
162	          c->cur.kind = TOK_END;
163	          return;
164	        }
165	
166	      c->p        = end;
167	      c->cur.kind = TOK_NUM;
168	      c->cur.num  = v;
169	      return;
170	    }
171	
172	  /* Identifier: function name or constant (pi / e). */
173	  if ((*c->p >= 'a' && *c->p <= 'z') || (*c->p >= 'A' && *c->p <= 'Z') ||
174	      *c->p == '_')
175	    {
176	      size_t n = 0;
177	      while (n + 1 < sizeof(c->cur.ident) &&
178	             ((*c->p >= 'a' && *c->p <= 'z') ||
179	              (*c->p >= 'A' && *c->p <= 'Z') ||
180	              (*c->p >= '0' && *c->p <= '9') ||
181	              *c->p == '_'))
182	        {
183	          c->cur.ident[n++] = *c->p++;
184	        }
185	
186	      c->cur.ident[n] = '\0';
187	      c->cur.kind     = TOK_IDENT;
188	      return;
189	    }
190	
191	  /* Single-character tokens. */
192	  switch (*c->p)
193	    {
194	      case '+':
195	      case '-':
196	      case '*':
197	      case '/':
198	      case '%':
199	      case '^':
200	        c->cur.kind = TOK_OP;
201	        c->cur.op   = *c->p++;
202	        return;
203	
204	      case '(':
205	        c->cur.kind = TOK_LPAREN;
206	        c->p++;
207	        return;
208	
209	      case ')':
210	        c->cur.kind = TOK_RPAREN;
211	        c->p++;
212	        return;
213	
214	      case ',':
215	        c->cur.kind = TOK_COMMA;
216	        c->p++;
217	        return;
218	
219	      default:
220	        calc_error(c, "unexpected character");
221	        c->cur.kind = TOK_END;
222	        c->p++;
223	        return;
224	    }
225	}
