227	/* Look up a function by name. Returns NULL if not found. */
228	static const struct calc_fn_s *calc_lookup_fn(const char *name)
229	{
230	  for (size_t i = 0; i < CALC_FN_COUNT; i++)
231	    {
232	      if (strcmp(g_calc_fns[i].name, name) == 0)
233	        {
234	          return &g_calc_fns[i];
235	        }
236	    }
237	
238	  return NULL;
239	}
