241	/* primary := number
242	 *         | ident ('(' expr (',' expr)? ')')?     # constant or call
243	 *         | '(' expr ')'
244	 *         | ('+' | '-') primary                    # unary
245	 */
246	static double parse_primary(struct calc_s *c)
247	{
248	  if (c->error)
249	    {
250	      return 0.0;
251	    }
252	
253	  if (c->cur.kind == TOK_NUM)
254	    {
255	      double v = c->cur.num;
256	      calc_next(c);
257	      return v;
258	    }
259	
260	  if (c->cur.kind == TOK_OP && (c->cur.op == '+' || c->cur.op == '-'))
261	    {
262	      char op = c->cur.op;
263	      calc_next(c);
264	      double v = parse_primary(c);
265	      return (op == '-') ? -v : v;
266	    }
267	
268	  if (c->cur.kind == TOK_LPAREN)
269	    {
270	      calc_next(c);
271	      double v = parse_expr(c);
272	      if (c->cur.kind != TOK_RPAREN)
273	        {
274	          calc_error(c, "missing ')'");
275	          return 0.0;
276	        }
277	
278	      calc_next(c);
279	      return v;
280	    }
281	
282	  if (c->cur.kind == TOK_IDENT)
283	    {
284	      char name[16];
285	      strlcpy(name, c->cur.ident, sizeof(name));
286	      calc_next(c);
287	
288	      /* Function call: ident '(' expr [',' expr] ')'. */
289	      if (c->cur.kind == TOK_LPAREN)
290	        {
291	          calc_next(c);
292	          double a = parse_expr(c);
293	          double b = 0.0;
294	
295	          if (c->cur.kind == TOK_COMMA)
296	            {
297	              calc_next(c);
298	              b = parse_expr(c);
299	            }
300	
301	          if (c->cur.kind != TOK_RPAREN)
302	            {
303	              calc_error(c, "missing ')' in call");
304	              return 0.0;
305	            }
306	
307	          calc_next(c);
308	
309	          const struct calc_fn_s *f = calc_lookup_fn(name);
310	          if (f == NULL)
311	            {
312	              calc_error(c, "unknown function");
313	              return 0.0;
314	            }
315	
316	          if (f->argc == 1)
317	            {
318	              if (f->fn1 == NULL)
319	                {
320	                  calc_error(c, "bad function");
321	                  return 0.0;
322	                }
323	
324	              return f->fn1(a);
325	            }
326	          else
327	            {
328	              if (f->fn2 == NULL)
329	                {
330	                  calc_error(c, "bad function");
331	                  return 0.0;
332	                }
333	
334	              return f->fn2(a, b);
335	            }
336	        }
337	
338	      /* Constant. */
339	      if (strcmp(name, "pi") == 0)
340	        {
341	          return M_PI;
342	        }
343	
344	      if (strcmp(name, "e") == 0)
345	        {
346	          return M_E;
347	        }
348	
349	      calc_error(c, "unknown identifier");
350	      return 0.0;
351	    }
352	
353	  calc_error(c, "unexpected token");
354	  return 0.0;
355	}
356	
357	/* factor := primary ('^' factor)?   # right-associative power */
358	static double parse_factor(struct calc_s *c)
359	{
360	  double base = parse_primary(c);
361	  if (c->error)
362	    {
363	      return 0.0;
364	    }
365	
366	  if (c->cur.kind == TOK_OP && c->cur.op == '^')
367	    {
368	      calc_next(c);
369	      double exp = parse_factor(c);   /* right-assoc */
370	      if (c->error)
371	        {
372	          return 0.0;
373	        }
374	
375	      return pow(base, exp);
376	    }
377	
378	  return base;
379	}
380	
381	/* term := factor (('*' | '/' | '%') factor)* */
382	static double parse_term(struct calc_s *c)
383	{
384	  double v = parse_factor(c);
385	  while (!c->error &&
386	         c->cur.kind == TOK_OP &&
387	         (c->cur.op == '*' || c->cur.op == '/' || c->cur.op == '%'))
388	    {
389	      char op = c->cur.op;
390	      calc_next(c);
391	      double rhs = parse_factor(c);
392	      if (c->error)
393	        {
394	          return 0.0;
395	        }
396	
397	      if (op == '*')
398	        {
399	          v *= rhs;
400	        }
401	      else if (op == '/')
402	        {
403	          if (rhs == 0.0)
404	            {
405	              calc_error(c, "division by zero");
406	              return 0.0;
407	            }
408	
409	          v /= rhs;
410	        }
411	      else  /* '%' */
412	        {
413	          if (rhs == 0.0)
414	            {
415	              calc_error(c, "modulo by zero");
416	              return 0.0;
417	            }
418	
419	          v = fmod(v, rhs);
420	        }
421	    }
422	
423	  return v;
424	}
425	
426	/* expr := term (('+' | '-') term)* */
427	static double parse_expr(struct calc_s *c)
428	{
429	  double v = parse_term(c);
430	  while (!c->error &&
431	         c->cur.kind == TOK_OP &&
432	         (c->cur.op == '+' || c->cur.op == '-'))
433	    {
434	      char op = c->cur.op;
435	      calc_next(c);
436	      double rhs = parse_term(c);
437	      if (c->error)
438	        {
439	          return 0.0;
440	        }
441	
442	      v = (op == '+') ? v + rhs : v - rhs;
443	    }
444	
445	  return v;
446	}
447	
448	/* Evaluate a calculator expression string. On success returns 0 and writes
449	 * the result to *out. On failure returns -1 and sets *errbuf to a short
450	 * reason (static string). */
451	static int calc_evaluate(const char *expr, double *out, const char **errbuf)
452	{
453	  struct calc_s c;
454	  c.p      = expr;
455	  c.error  = false;
456	  c.errmsg = NULL;
457	
458	  calc_next(&c);
459	  double v = parse_expr(&c);
460	  if (c.error)
461	    {
462	      if (errbuf != NULL)
463	        {
464	          *errbuf = c.errmsg ? c.errmsg : "syntax error";
465	        }
466	
467	      return -1;
468	    }
469	
470	  if (c.cur.kind != TOK_END)
471	    {
472	      if (errbuf != NULL)
473	        {
474	          *errbuf = "unexpected trailing input";
475	        }
476	
477	      return -1;
478	    }
479	
480	  if (isinf(v) || isnan(v))
481	    {
482	      if (errbuf != NULL)
483	        {
484	          *errbuf = "result is not finite";
485	        }
486	
487	      return -1;
488	    }
489	
490	  *out = v;
491	  return 0;
492	}
