497	
498	/* Build the JSON-RPC response envelope and send it as an mcp text frame. */
499	static int send_mcp_frame(struct xiaozhi_ws_s *ws, const char *session_id,
500	                          cJSON *result)
501	{
502	  int ret;
503	  char *json;
504	
505	  cJSON *frame   = cJSON_CreateObject();
506	
507	  cJSON_AddStringToObject(frame, "type", "mcp");
508	  cJSON_AddStringToObject(frame, "session_id", session_id);
509	
510	  /* Adopt the caller's JSON-RPC response as the payload. Detaching the
511	   * root's children one by one is fragile (cJSON_DetachItemViaPointer on
512	   * names that may already exist), so serialize-and-reparse the whole
513	   * response into a fresh payload object instead.
514	   */
515	  {
516	    char *rstr = cJSON_PrintUnformatted(result);
517	    cJSON *payload = cJSON_Parse(rstr ? rstr : "{}");
518	    free(rstr);
519	    cJSON_AddItemToObject(frame, "payload", payload);
520	  }
521	
522	  json = cJSON_PrintUnformatted(frame);
523	  if (json != NULL)
524	    {
525	      ret = xiaozhi_ws_send_text(ws, json, strlen(json));
526	      free(json);
527	    }
528	  else
529	    {
530	      ret = -ENOMEM;
531	    }
532	
533	  cJSON_Delete(frame);
534	  cJSON_Delete(result);
535	  return ret;
536	}
