538	/* Build a JSON-RPC result object for the given request id. */
539	static cJSON *reply_result(cJSON *id)
540	{
541	  cJSON *resp = cJSON_CreateObject();
542	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
543	  cJSON_AddItemReferenceToObject(resp, "id", id);
544	  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
545	  return resp;
546	}
547	
548	/* Build a JSON-RPC error object for the given request id and code/message. */
549	static cJSON *reply_error(cJSON *id, int code, const char *message)
550	{
551	  cJSON *resp = cJSON_CreateObject();
552	  cJSON *err  = cJSON_CreateObject();
553	
554	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
555	  cJSON_AddItemReferenceToObject(resp, "id", id);
556	  cJSON_AddItemToObject(resp, "error", err);
557	  cJSON_AddNumberToObject(err, "code", code);
558	  cJSON_AddStringToObject(err, "message", message);
559	  return resp;
560	}
