562	/* Build a text content block, the shape MCP tools/call results use. */
563	static cJSON *make_text_result(const char *text)
564	{
565	  cJSON *content = cJSON_CreateArray();
566	  cJSON *item    = cJSON_CreateObject();
567	
568	  cJSON_AddItemToArray(content, item);
569	  cJSON_AddStringToObject(item, "type", "text");
570	  cJSON_AddStringToObject(item, "text", text);
571	  return content;
572	}
