575	 * Private: tool handlers
576	 ****************************************************************************/
577	
578	/* Handle a tools/call request. Returns a JSON-RPC response object (either
579	 * a result with content, or an error) with the request id already set.
580	 * Caller frees it.
581	 */
582	static cJSON *handle_tools_call(cJSON *id, cJSON *params)
583	{
584	  cJSON *name = cJSON_GetObjectItem(params, "name");
585	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
586	  const char *namestr = cJSON_IsString(name) ? name->valuestring : NULL;
587	
588	  if (namestr == NULL)
589	    {
590	      return reply_error(id, -32602, "Missing tool name");
591	    }
592	
593	  if (!cJSON_IsObject(args))
594	    {
595	      args = NULL;   /* arguments are optional for some tools */
596	    }
597	
598	  /* calculator: evaluate a math expression. */
599	  if (strcmp(namestr, XIAOZHI_MCP_TOOL_CALCULATOR) == 0)
600	    {
601	      cJSON *expr = args ? cJSON_GetObjectItem(args, "python_expression") : NULL;
602	      if (!cJSON_IsString(expr))
603	        {
604	          return reply_error(id, -32602, "Missing python_expression");
605	        }
606	
607	      double result;
608	      const char *err = NULL;
609	      if (calc_evaluate(expr->valuestring, &result, &err) != 0)
610	        {
611	          /* On a parse/eval error, MCP convention is to return an
612	           * isError result rather than a JSON-RPC error, so the LLM can
613	           * see the message and retry. */
614	          cJSON *resp = reply_result(id);
615	          cJSON *errtext = make_text_result(err ? err : "syntax error");
616	          cJSON *resultobj = cJSON_GetObjectItem(resp, "result");
617	          cJSON_AddItemToObject(resultobj, "content", errtext);
618	          cJSON_AddBoolToObject(resultobj, "isError", true);
619	          return resp;
620	        }
621	
622	      /* Success: return the numeric result as a text content block. */
623	      char buf[64];
624	      snprintf(buf, sizeof(buf), "%.12g", result);
625	
626	      cJSON *resp     = reply_result(id);
627	      cJSON *resultobj = cJSON_GetObjectItem(resp, "result");
628	      cJSON_AddItemToObject(resultobj, "content", make_text_result(buf));
629	      cJSON_AddBoolToObject(resultobj, "isError", false);
630	      return resp;
631	    }
632	
633	  return reply_error(id, -32601, "Unknown tool");
634	}
