661	void xiaozhi_mcp_handle_message(struct xiaozhi_ws_s *ws,
662	                                const char *session_id,
663	                                cJSON *payload)
664	{
665	  cJSON *method = cJSON_GetObjectItem(payload, "method");
666	  cJSON *id     = cJSON_GetObjectItem(payload, "id");
667	  cJSON *params = cJSON_GetObjectItem(payload, "params");
668	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
669	
670	  if (mstr == NULL)
671	    {
672	      cJSON *resp = reply_error(id, -32600, "Missing method");
673	      send_mcp_frame(ws, session_id, resp);
674	      return;
675	    }
676	
677	  printf("[xiaozhi] mcp: method=%s id=%d\n", mstr,
678	         cJSON_IsNumber(id) ? (int)id->valuedouble : -1);
679	
680	  if (strcmp(mstr, "initialize") == 0)
681	    {
682	      cJSON *resp     = reply_result(id);
683	      cJSON *result   = cJSON_GetObjectItem(resp, "result");
684	      cJSON *info     = cJSON_CreateObject();
685	      cJSON *caps     = cJSON_CreateObject();
686	      cJSON *toolscap = cJSON_CreateObject();
687	
688	      cJSON_AddStringToObject(result, "protocolVersion",
689	                              XIAOZHI_MCP_PROTOCOL_VERSION);
690	      cJSON_AddItemToObject(result, "serverInfo", info);
691	      cJSON_AddStringToObject(info, "name", XIAOZHI_MCP_SERVER_NAME);
692	      cJSON_AddStringToObject(info, "version", XIAOZHI_MCP_SERVER_VERSION);
693	      cJSON_AddItemToObject(result, "capabilities", caps);
694	      cJSON_AddItemToObject(caps, "tools", toolscap);
695	      cJSON_AddBoolToObject(toolscap, "listChanged", false);
696	
697	      send_mcp_frame(ws, session_id, resp);
698	      return;
699	    }
700	
701	  if (strcmp(mstr, "tools/list") == 0)
702	    {
703	      cJSON *resp   = reply_result(id);
704	      cJSON *result = cJSON_GetObjectItem(resp, "result");
705	      cJSON *tools  = cJSON_CreateArray();
706	
707	      /* calculator */
708	      {
709	        cJSON *schema = cJSON_CreateObject();
710	        cJSON *props  = cJSON_CreateObject();
711	        cJSON *expr   = cJSON_CreateObject();
712	        cJSON *reqd   = cJSON_CreateArray();
713	
714	        cJSON_AddStringToObject(schema, "type", "object");
715	        cJSON_AddItemToObject(schema, "properties", props);
716	        cJSON_AddItemToObject(props, "python_expression", expr);
717	        cJSON_AddStringToObject(expr, "type", "string");
718	        cJSON_AddStringToObject(expr, "description",
719	          "A math expression to evaluate, e.g. '2+3*4', 'sqrt(2)', "
720	          "'sin(pi/2)', 'pow(2,10)'. Supports + - * / % ^, parentheses, "
721	          "and functions sqrt/sin/cos/tan/exp/log/log10/floor/ceil/abs/pow/"
722	          "atan2/max/min plus constants pi and e.");
723	        cJSON_AddItemToObject(schema, "required", reqd);
724	        cJSON_AddItemToArray(reqd, cJSON_CreateString("python_expression"));
725	
726	        cJSON_AddItemToArray(tools,
727	          make_tool_descriptor(XIAOZHI_MCP_TOOL_CALCULATOR,
728	            "Evaluate a mathematical expression and return the result. "
729	            "Use this for any arithmetic calculation requested by the "
730	            "user.",
731	            schema));
732	      }
733	
734	      cJSON_AddItemToObject(result, "tools", tools);
735	      send_mcp_frame(ws, session_id, resp);
736	      return;
737	    }
738	
739	  if (strcmp(mstr, "tools/call") == 0)
740	    {
741	      cJSON *resp = handle_tools_call(id, params ? params : cJSON_CreateObject());
742	      send_mcp_frame(ws, session_id, resp);
743	      return;
744	    }
745	
746	  /* Notifications (no id) are not answered; other methods are unsupported. */
747	  if (id == NULL)
748	    {
749	      return;
750	    }
751	
752	  {
753	    char msg[64];
754	    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
755	    send_mcp_frame(ws, session_id, reply_error(id, -32601, msg));
756	  }
757	}
