/****************************************************************************
 * apps/examples/mcp_server/mcp_server_main.c
 *
 * A local MCP (Model Context Protocol) server speaking the stdio transport.
 * It exposes a single tool, "start_app", that launches a built-in NuttX
 * application on the device via posix_spawn().
 *
 * Transport (per the MCP stdio spec): messages are newline-delimited JSON-RPC
 * 2.0 objects — one request per line on stdin, one response per line on
 * stdout, no embedded newlines. stderr is used for logging only.
 *
 * This process is spawned by the xiaozhi_voice app, which acts as the MCP
 * client and forwards the cloud's MCP requests to this server over its
 * stdin/stdout pipes.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <spawn.h>
#include <sys/wait.h>
#include <errno.h>

#include <netutils/cJSON.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define MCP_PROTOCOL_VERSION "2024-11-05"
#define MCP_SERVER_NAME       "mcp-server"
#define MCP_SERVER_VERSION    "1.0"

#define MCP_LINE_MAX  2048

/* The fixed list of applications that can be launched. Each entry maps a
 * stable, human-friendly name to the NuttX builtin program name passed to
 * posix_spawn(). Extend this table to expose more apps.
 */
struct app_entry_s
{
  const char *name;   /* name exposed to the LLM via tools/list enum      */
  const char *prog;   /* builtin program name passed to posix_spawn()    */
};

static const struct app_entry_s g_apps[] =
{
  { "hello", "hello" },
};

#define APP_COUNT (sizeof(g_apps) / sizeof(g_apps[0]))

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static cJSON *reply_result(cJSON *id);
static cJSON *reply_error(cJSON *id, int code, const char *message);
static void send_response(cJSON *resp);
static cJSON *handle_initialize(cJSON *id);
static cJSON *handle_tools_list(cJSON *id);
static cJSON *handle_tools_call(cJSON *id, cJSON *params);
static const struct app_entry_s *find_app(const char *name);

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Build a JSON-RPC result object for the given request id. */
static cJSON *reply_result(cJSON *id)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
  return resp;
}

/* Build a JSON-RPC error object for the given request id and code/message. */
static cJSON *reply_error(cJSON *id, int code, const char *message)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON *err  = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "error", err);
  cJSON_AddNumberToObject(err, "code", code);
  cJSON_AddStringToObject(err, "message", message);
  return resp;
}

/* Serialize a JSON-RPC response as one line on stdout (newline-delimited). */
static void send_response(cJSON *resp)
{
  char *json = cJSON_PrintUnformatted(resp);
  if (json != NULL)
    {
      printf("%s\n", json);
      fflush(stdout);
      free(json);
    }

  cJSON_Delete(resp);
}

/* Build a single text content block (the shape tools/call results use). */
static cJSON *make_text_content(const char *text)
{
  cJSON *content = cJSON_CreateArray();
  cJSON *item    = cJSON_CreateObject();
  cJSON_AddItemToArray(content, item);
  cJSON_AddStringToObject(item, "type", "text");
  cJSON_AddStringToObject(item, "text", text);
  return content;
}

static const struct app_entry_s *find_app(const char *name)
{
  for (size_t i = 0; i < APP_COUNT; i++)
    {
      if (strcmp(g_apps[i].name, name) == 0)
        {
          return &g_apps[i];
        }
    }

  return NULL;
}

/* initialize: report server info, protocol version, and capabilities. */
static cJSON *handle_initialize(cJSON *id)
{
  cJSON *resp     = reply_result(id);
  cJSON *result   = cJSON_GetObjectItem(resp, "result");
  cJSON *info     = cJSON_CreateObject();
  cJSON *caps     = cJSON_CreateObject();
  cJSON *toolscap = cJSON_CreateObject();

  cJSON_AddStringToObject(result, "protocolVersion", MCP_PROTOCOL_VERSION);
  cJSON_AddItemToObject(result, "serverInfo", info);
  cJSON_AddStringToObject(info, "name", MCP_SERVER_NAME);
  cJSON_AddStringToObject(info, "version", MCP_SERVER_VERSION);
  cJSON_AddItemToObject(result, "capabilities", caps);
  cJSON_AddItemToObject(caps, "tools", toolscap);
  cJSON_AddBoolToObject(toolscap, "listChanged", false);
  return resp;
}

/* tools/list: advertise the start_app tool and the app name enum. */
static cJSON *handle_tools_list(cJSON *id)
{
  cJSON *resp    = reply_result(id);
  cJSON *result  = cJSON_GetObjectItem(resp, "result");
  cJSON *tools  = cJSON_CreateArray();
  cJSON *tool   = cJSON_CreateObject();
  cJSON *schema = cJSON_CreateObject();
  cJSON *props  = cJSON_CreateObject();
  cJSON *apparg = cJSON_CreateObject();
  cJSON *reqd   = cJSON_CreateArray();
  cJSON *enumv  = cJSON_CreateArray();

  cJSON_AddStringToObject(tool, "name", "start_app");
  cJSON_AddStringToObject(tool, "description",
    "启动设备上的一个应用。通过 app_name 指定要打开的应用，"
    "例如语音指令\"打开 hello 应用\"时调用此工具。");
  cJSON_AddItemToObject(tool, "inputSchema", schema);

  cJSON_AddStringToObject(schema, "type", "object");
  cJSON_AddItemToObject(schema, "properties", props);
  cJSON_AddItemToObject(props, "app_name", apparg);
  cJSON_AddStringToObject(apparg, "type", "string");
  cJSON_AddStringToObject(apparg, "description", "要启动的应用名称");
  cJSON_AddItemToObject(apparg, "enum", enumv);
  for (size_t i = 0; i < APP_COUNT; i++)
    {
      cJSON_AddItemToArray(enumv, cJSON_CreateString(g_apps[i].name));
    }

  cJSON_AddItemToObject(schema, "required", reqd);
  cJSON_AddItemToArray(reqd, cJSON_CreateString("app_name"));

  cJSON_AddItemToArray(tools, tool);
  cJSON_AddItemToObject(result, "tools", tools);
  return resp;
}

/* tools/call: dispatch by name. Only "start_app" is supported. */
static cJSON *handle_tools_call(cJSON *id, cJSON *params)
{
  cJSON *name = cJSON_GetObjectItem(params, "name");
  const char *namestr = cJSON_IsString(name) ? name->valuestring : NULL;

  if (namestr == NULL)
    {
      return reply_error(id, -32602, "Missing tool name");
    }

  if (strcmp(namestr, "start_app") != 0)
    {
      return reply_error(id, -32601, "Unknown tool");
    }

  cJSON *args     = cJSON_GetObjectItem(params, "arguments");
  cJSON *appname = (args != NULL) ? cJSON_GetObjectItem(args, "app_name") : NULL;
  const char *appstr = cJSON_IsString(appname) ? appname->valuestring : NULL;

  if (appstr == NULL)
    {
      /* MCP convention: return an isError result so the LLM can react. */
      cJSON *resp     = reply_result(id);
      cJSON *result   = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Missing app_name argument"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  const struct app_entry_s *app = find_app(appstr);
  if (app == NULL)
    {
      char msg[64];
      cJSON *resp;
      cJSON *result;
      snprintf(msg, sizeof(msg), "Unknown application: %s", appstr);
      resp   = reply_result(id);
      result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content", make_text_content(msg));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  /* Launch the builtin application. argv[0] is the program name. */
  {
    char *argv[2] = { (char *)app->prog, NULL };
    pid_t pid;
    int ret = posix_spawn(&pid, app->prog, NULL, NULL, argv, NULL);
    if (ret != 0)
      {
        char msg[64];
        cJSON *resp;
        cJSON *result;
        snprintf(msg, sizeof(msg), "Failed to launch %s: %d", appstr, ret);
        resp   = reply_result(id);
        result = cJSON_GetObjectItem(resp, "result");
        cJSON_AddItemToObject(result, "content", make_text_content(msg));
        cJSON_AddBoolToObject(result, "isError", true);
        return resp;
      }

    /* Don't wait — let the launched app run independently. */
    {
      char msg[64];
      cJSON *resp;
      cJSON *result;
      snprintf(msg, sizeof(msg), "已启动应用 %s", appstr);
      resp   = reply_result(id);
      result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content", make_text_content(msg));
      cJSON_AddBoolToObject(result, "isError", false);
      return resp;
    }
  }
}

/* Dispatch one JSON-RPC request object to a handler and return the response. */
static cJSON *dispatch(cJSON *req)
{
  cJSON *method = cJSON_GetObjectItem(req, "method");
  cJSON *id     = cJSON_GetObjectItem(req, "id");
  cJSON *params = cJSON_GetObjectItem(req, "params");
  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;

  if (mstr == NULL)
    {
      return reply_error(id, -32600, "Missing method");
    }

  if (strcmp(mstr, "initialize") == 0)
    {
      return handle_initialize(id);
    }

  if (strcmp(mstr, "tools/list") == 0)
    {
      return handle_tools_list(id);
    }

  if (strcmp(mstr, "tools/call") == 0)
    {
      return handle_tools_call(id, params ? params : cJSON_CreateObject());
    }

  /* Notifications (no id) are not answered. */
  if (id == NULL)
    {
      return NULL;
    }

  {
    char msg[80];
    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
    return reply_error(id, -32601, msg);
  }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  char line[MCP_LINE_MAX];

  fprintf(stderr, "[mcp_server] started (stdio transport)\n");

  /* Read newline-delimited JSON-RPC requests from stdin, one per line. */
  while (fgets(line, sizeof(line), stdin) != NULL)
    {
      /* Strip trailing newline. */
      size_t len = strlen(line);
      while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
        {
          line[--len] = '\0';
        }

      if (len == 0)
        {
          continue;
        }

      cJSON *req = cJSON_Parse(line);
      if (req == NULL)
        {
          cJSON *resp = reply_error(NULL, -32700, "Parse error");
          send_response(resp);
          continue;
        }

      cJSON *resp = dispatch(req);
      cJSON_Delete(req);

      if (resp != NULL)
        {
          send_response(resp);
        }
    }

  fprintf(stderr, "[mcp_server] stdin closed, exiting\n");
  return 0;
}

/****************************************************************************
 * apps/examples/xiaozhi_voice/xiaozhi_mcp.c
 *
 * MCP (Model Context Protocol) client side for the xiaozhi voice app.
 * See xiaozhi_mcp.h for an overview.
 *
 * The cloud sends MCP JSON-RPC requests inside WebSocket text frames:
 *
 *   { "type": "mcp", "payload": <jsonrpc request> }
 *
 * This module is a *client*: it spawns a local MCP server ("mcp_server",
 * a built-in NuttX program) as a subprocess and forwards each cloud
 * request to it over the server's stdin pipe, then reads the server's
 * response from its stdout pipe and relays it back to the cloud as:
 *
 *   { "type":"mcp", "session_id":<sid>, "payload": <jsonrpc response> }
 *
 * The stdio transport uses newline-delimited JSON (one JSON-RPC object per
 * line, no embedded newlines), matching the MCP stdio spec and the
 * reference mcp-calculator-main/mcp_pipe.py bridge.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <spawn.h>
#include <errno.h>

#include <netutils/cJSON.h>

#include "xiaozhi_mcp.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Name of the local MCP server built-in program to spawn. */
#define MCP_SERVER_PROGNAME  "mcp_server"

/* Maximum length of one stdio JSON-RPC line (requests and responses). The
 * messages exchanged here are short; tools/list is the largest. */
#define MCP_LINE_MAX  4096

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* State of the local MCP server subprocess and its stdin/stdout pipes. */
struct mcp_client_s
{
  bool   spawned;          /* server process has been started */
  pid_t  pid;              /* server process id */
  int    stdin_fd;         /* write end → server stdin  */
  int    stdout_fd;        /* read end  ← server stdout */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct mcp_client_s g_client;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Send one JSON-RPC object as a newline-delimited line to the server stdin. */
static int client_write_request(cJSON *req)
{
  char *json = cJSON_PrintUnformatted(req);
  if (json == NULL)
    {
      return -ENOMEM;
    }

  size_t len    = strlen(json);
  size_t total  = len + 1;          /* +1 for newline */
  int ret      = 0;

  if (total > MCP_LINE_MAX)
    {
      free(json);
      return -E2BIG;
    }

  /* Write the JSON followed by a newline. */
  if (write(g_client.stdin_fd, json, len) != (ssize_t)len)
    {
      ret = -EIO;
    }
  else if (write(g_client.stdin_fd, "\n", 1) != 1)
    {
      ret = -EIO;
    }

  free(json);
  return ret;
}

/* Read one newline-delimited JSON-RPC line from the server stdout and parse
 * it. Returns a cJSON object (caller frees) or NULL on error/EOF. */
static cJSON *client_read_response(void)
{
  char buf[MCP_LINE_MAX];
  size_t len = 0;
  int ret;

  /* Read one byte at a time until newline or buffer full. MCP responses are
   * short; this is simple and avoids line-buffering subtleties. */
  while (len + 1 < sizeof(buf))
    {
      ssize_t n = read(g_client.stdout_fd, buf + len, 1);
      if (n <= 0)
        {
          /* EOF or error — server gone. */
          return NULL;
        }

      if (buf[len] == '\n')
        {
          break;
        }

      len++;
    }

  if (len == 0)
    {
      return NULL;
    }

  buf[len] = '\0';
  cJSON *resp = cJSON_Parse(buf);
  return resp;
}

/* Tear down the server subprocess and close the pipes. */
static void client_teardown(void)
{
  if (g_client.stdin_fd >= 0)
    {
      close(g_client.stdin_fd);
      g_client.stdin_fd = -1;
    }

  if (g_client.stdout_fd >= 0)
    {
      close(g_client.stdout_fd);
      g_client.stdout_fd = -1;
    }

  g_client.spawned = false;
  g_client.pid     = 0;
}

/* Spawn the local MCP server subprocess with stdin/stdout redirected to a
 * pair of pipes. Returns 0 on success, negative errno on failure. */
static int client_ensure_spawned(void)
{
  int to_server[2];     /* [0]=read (server stdin), [1]=write (client) */
  int from_server[2];   /* [0]=read (client),         [1]=write (server) */
  posix_spawn_file_actions_t actions;
  char *argv[2] = { (char *)MCP_SERVER_PROGNAME, NULL };
  int ret;

  if (g_client.spawned)
    {
      return 0;
    }

  if (pipe(to_server) != 0)
    {
      printf("[xiaozhi] mcp: to_server pipe failed: %d\n", errno);
      return -errno;
    }

  if (pipe(from_server) != 0)
    {
      printf("[xiaozhi] mcp: from_server pipe failed: %d\n", errno);
      close(to_server[0]);
      close(to_server[1]);
      return -errno;
    }

  ret = posix_spawn_file_actions_init(&actions);
  if (ret != 0)
    {
      goto fail_pipes;
    }

  /* Server stdin  = read end of to_server pipe. */
  ret = posix_spawn_file_actions_adddup2(&actions, to_server[0], 0);
  if (ret != 0)
    {
      goto fail_actions;
    }

  /* Server stdout = write end of from_server pipe. */
  ret = posix_spawn_file_actions_adddup2(&actions, from_server[1], 1);
  if (ret != 0)
    {
      goto fail_actions;
    }

  /* Close the pipe ends the server does not need in its own fd table. */
  posix_spawn_file_actions_addclose(&actions, to_server[0]);
  posix_spawn_file_actions_addclose(&actions, to_server[1]);
  posix_spawn_file_actions_addclose(&actions, from_server[0]);
  posix_spawn_file_actions_addclose(&actions, from_server[1]);

  ret = posix_spawn(&g_client.pid, MCP_SERVER_PROGNAME, &actions, NULL,
                    argv, NULL);

  posix_spawn_file_actions_destroy(&actions);

  if (ret != 0)
    {
      printf("[xiaozhi] mcp: posix_spawn(%s) failed: %d\n",
             MCP_SERVER_PROGNAME, ret);
      goto fail_pipes;
    }

  /* Parent keeps the write end of to_server and the read end of from_server;
   * close the other ends. */
  close(to_server[0]);
  close(from_server[1]);

  g_client.stdin_fd  = to_server[1];
  g_client.stdout_fd = from_server[0];
  g_client.spawned   = true;

  printf("[xiaozhi] mcp: spawned %s (pid=%d)\n",
         MCP_SERVER_PROGNAME, g_client.pid);
  return 0;

fail_actions:
  posix_spawn_file_actions_destroy(&actions);

fail_pipes:
  close(to_server[0]);
  close(to_server[1]);
  close(from_server[0]);
  close(from_server[1]);
  return -ret;
}

/* Forward a JSON-RPC request to the local server and relay its response
 * back as an "mcp" frame to the cloud. On any client/transport error, send
 * a JSON-RPC error response to the cloud instead. */
static void mcp_forward(struct xiaozhi_ws_s *ws, const char *session_id,
                        cJSON *req)
{
  int ret;

  ret = client_ensure_spawned();
  if (ret != 0)
    {
      cJSON *err = cJSON_CreateObject();
      cJSON_AddStringToObject(err, "jsonrpc", "2.0");
      cJSON_AddItemReferenceToObject(err, "id", cJSON_GetObjectItem(req, "id"));
      cJSON_AddItemToObject(err, "error", cJSON_CreateObject());
      {
        cJSON *eobj = cJSON_GetObjectItem(err, "error");
        char msg[64];
        snprintf(msg, sizeof(msg),
                 "MCP server unavailable: %d", ret);
        cJSON_AddNumberToObject(eobj, "code", -32603);
        cJSON_AddStringToObject(eobj, "message", msg);
      }

      /* Wrap the error in an mcp frame. */
      {
        cJSON *frame = cJSON_CreateObject();
        cJSON_AddStringToObject(frame, "type", "mcp");
        cJSON_AddStringToObject(frame, "session_id", session_id);
        cJSON_AddItemToObject(frame, "payload", err);
        char *j = cJSON_PrintUnformatted(frame);
        if (j != NULL)
          {
            xiaozhi_ws_send_text(ws, j, strlen(j));
            free(j);
          }

        cJSON_Delete(frame);
      }
      return;
    }

  ret = client_write_request(req);
  if (ret != 0)
    {
      printf("[xiaozhi] mcp: write to server failed: %d\n", ret);
      client_teardown();
      return;
    }

  cJSON *resp = client_read_response();
  if (resp == NULL)
    {
      printf("[xiaozhi] mcp: no response from server\n");
      client_teardown();
      return;
    }

  /* Wrap the server's JSON-RPC response in an mcp frame and send to cloud. */
  {
    cJSON *frame = cJSON_CreateObject();
    cJSON_AddStringToObject(frame, "type", "mcp");
    cJSON_AddStringToObject(frame, "session_id", session_id);
    cJSON_AddItemToObject(frame, "payload", resp);   /* frame owns resp */
    char *j = cJSON_PrintUnformatted(frame);
    if (j != NULL)
      {
        xiaozhi_ws_send_text(ws, j, strlen(j));
        free(j);
      }

    cJSON_Delete(frame);
  }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void xiaozhi_mcp_add_features(cJSON *features)
{
  if (features == NULL)
    {
      return;
    }

  cJSON_AddBoolToObject(features, "mcp", true);
}

void xiaozhi_mcp_handle_message(struct xiaozhi_ws_s *ws,
                                const char *session_id,
                                cJSON *payload)
{
  cJSON *method = cJSON_GetObjectItem(payload, "method");
  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;

  if (mstr == NULL)
    {
      printf("[xiaozhi] mcp: payload has no method\n");
      return;
    }

  printf("[xiaozhi] mcp: forwarding method=%s\n", mstr);

  /* Forward the request object verbatim to the local MCP server. */
  mcp_forward(ws, session_id, payload);
}

