55	/* State of the local MCP server subprocess and its stdin/stdout pipes. */
56	struct mcp_client_s
57	{
58	  bool   spawned;          /* server process has been started */
59	  pid_t  pid;              /* server process id */
60	  int    stdin_fd;         /* write end → server stdin  */
61	  int    stdout_fd;        /* read end  ← server stdout */
62	};
