74	/* Send one JSON-RPC object as a newline-delimited line to the server stdin. */
75	static int client_write_request(cJSON *req)
76	{
77	  char *json = cJSON_PrintUnformatted(req);
78	  if (json == NULL)
79	    {
80	      return -ENOMEM;
81	    }
82	
83	  size_t len    = strlen(json);
84	  size_t total  = len + 1;          /* +1 for newline */
85	  int ret      = 0;
86	
87	  if (total > MCP_LINE_MAX)
88	    {
89	      free(json);
90	      return -E2BIG;
91	    }
92	
93	  /* Write the JSON followed by a newline. */
94	  if (write(g_client.stdin_fd, json, len) != (ssize_t)len)
95	    {
96	      ret = -EIO;
97	    }
98	  else if (write(g_client.stdin_fd, "\n", 1) != 1)
99	    {
100	      ret = -EIO;
101	    }
102	
103	  free(json);
104	  return ret;
105	}
106	
107	/* Read one newline-delimited JSON-RPC line from the server stdout and parse
108	 * it. Returns a cJSON object (caller frees) or NULL on error/EOF. */
109	static cJSON *client_read_response(void)
110	{
111	  char buf[MCP_LINE_MAX];
112	  size_t len = 0;
113	  int ret;
114	
115	  /* Read one byte at a time until newline or buffer full. MCP responses are
116	   * short; this is simple and avoids line-buffering subtleties. */
117	  while (len + 1 < sizeof(buf))
118	    {
119	      ssize_t n = read(g_client.stdout_fd, buf + len, 1);
120	      if (n <= 0)
121	        {
122	          /* EOF or error — server gone. */
123	          return NULL;
124	        }
125	
126	      if (buf[len] == '\n')
127	        {
128	          break;
129	        }
130	
131	      len++;
132	    }
133	
134	  if (len == 0)
135	    {
136	      return NULL;
137	    }
138	
139	  buf[len] = '\0';
140	  cJSON *resp = cJSON_Parse(buf);
141	  return resp;
142	}
