148	    {
149	      close(g_client.stdin_fd);
150	      g_client.stdin_fd = -1;
151	    }
152	
153	  if (g_client.stdout_fd >= 0)
154	    {
155	      close(g_client.stdout_fd);
156	      g_client.stdout_fd = -1;
157	    }
158	
