163	/* Spawn the local MCP server subprocess with stdin/stdout redirected to a
164	 * pair of pipes. Returns 0 on success, negative errno on failure. */
165	static int client_ensure_spawned(void)
166	{
167	  int to_server[2];     /* [0]=read (server stdin), [1]=write (client) */
168	  int from_server[2];   /* [0]=read (client),         [1]=write (server) */
169	  posix_spawn_file_actions_t actions;
170	  char *argv[2] = { (char *)MCP_SERVER_PROGNAME, NULL };
171	  int ret;
172	
173	  if (g_client.spawned)
174	    {
175	      return 0;
176	    }
177	
178	  if (pipe(to_server) != 0)
179	    {
180	      printf("[xiaozhi] mcp: to_server pipe failed: %d\n", errno);
181	      return -errno;
182	    }
183	
184	  if (pipe(from_server) != 0)
185	    {
186	      printf("[xiaozhi] mcp: from_server pipe failed: %d\n", errno);
187	      close(to_server[0]);
188	      close(to_server[1]);
189	      return -errno;
190	    }
191	
192	  ret = posix_spawn_file_actions_init(&actions);
193	  if (ret != 0)
194	    {
195	      goto fail_pipes;
196	    }
197	
198	  /* Server stdin  = read end of to_server pipe. */
199	  ret = posix_spawn_file_actions_adddup2(&actions, to_server[0], 0);
200	  if (ret != 0)
201	    {
202	      goto fail_actions;
203	    }
204	
205	  /* Server stdout = write end of from_server pipe. */
206	  ret = posix_spawn_file_actions_adddup2(&actions, from_server[1], 1);
207	  if (ret != 0)
208	    {
209	      goto fail_actions;
210	    }
211	
212	  /* Close the pipe ends the server does not need in its own fd table. */
213	  posix_spawn_file_actions_addclose(&actions, to_server[0]);
214	  posix_spawn_file_actions_addclose(&actions, to_server[1]);
215	  posix_spawn_file_actions_addclose(&actions, from_server[0]);
216	  posix_spawn_file_actions_addclose(&actions, from_server[1]);
217	
218	  ret = posix_spawn(&g_client.pid, MCP_SERVER_PROGNAME, &actions, NULL,
219	                    argv, NULL);
220	
221	  posix_spawn_file_actions_destroy(&actions);
222	
223	  if (ret != 0)
224	    {
225	      printf("[xiaozhi] mcp: posix_spawn(%s) failed: %d\n",
226	             MCP_SERVER_PROGNAME, ret);
227	      goto fail_pipes;
228	    }
229	
230	  /* Parent keeps the write end of to_server and the read end of from_server;
231	   * close the other ends. */
232	  close(to_server[0]);
233	  close(from_server[1]);
234	
235	  g_client.stdin_fd  = to_server[1];
236	  g_client.stdout_fd = from_server[0];
237	  g_client.spawned   = true;
238	
239	  printf("[xiaozhi] mcp: spawned %s (pid=%d)\n",
240	         MCP_SERVER_PROGNAME, g_client.pid);
241	  return 0;
242	
243	fail_actions:
244	  posix_spawn_file_actions_destroy(&actions);
245	
246	fail_pipes:
247	  close(to_server[0]);
248	  close(to_server[1]);
249	  close(from_server[0]);
250	  close(from_server[1]);
251	  return -ret;
252	}
