254	/* Forward a JSON-RPC request to the local server and relay its response
255	 * back as an "mcp" frame to the cloud. On any client/transport error, send
256	 * a JSON-RPC error response to the cloud instead. */
257	static void mcp_forward(struct xiaozhi_ws_s *ws, const char *session_id,
258	                        cJSON *req)
259	{
260	  int ret;
261	
262	  ret = client_ensure_spawned();
263	  if (ret != 0)
264	    {
265	      cJSON *err = cJSON_CreateObject();
266	      cJSON_AddStringToObject(err, "jsonrpc", "2.0");
267	      cJSON_AddItemReferenceToObject(err, "id", cJSON_GetObjectItem(req, "id"));
268	      cJSON_AddItemToObject(err, "error", cJSON_CreateObject());
269	      {
270	        cJSON *eobj = cJSON_GetObjectItem(err, "error");
271	        char msg[64];
272	        snprintf(msg, sizeof(msg),
273	                 "MCP server unavailable: %d", ret);
274	        cJSON_AddNumberToObject(eobj, "code", -32603);
275	        cJSON_AddStringToObject(eobj, "message", msg);
276	      }
277	
278	      /* Wrap the error in an mcp frame. */
279	      {
280	        cJSON *frame = cJSON_CreateObject();
281	        cJSON_AddStringToObject(frame, "type", "mcp");
282	        cJSON_AddStringToObject(frame, "session_id", session_id);
283	        cJSON_AddItemToObject(frame, "payload", err);
284	        char *j = cJSON_PrintUnformatted(frame);
285	        if (j != NULL)
286	          {
287	            xiaozhi_ws_send_text(ws, j, strlen(j));
288	            free(j);
289	          }
290	
291	        cJSON_Delete(frame);
292	      }
293	      return;
294	    }
295	
296	  ret = client_write_request(req);
297	  if (ret != 0)
298	    {
299	      printf("[xiaozhi] mcp: write to server failed: %d\n", ret);
300	      client_teardown();
301	      return;
302	    }
303	
304	  cJSON *resp = client_read_response();
305	  if (resp == NULL)
306	    {
307	      printf("[xiaozhi] mcp: no response from server\n");
308	      client_teardown();
309	      return;
310	    }
311	
312	  /* Wrap the server's JSON-RPC response in an mcp frame and send to cloud. */
313	  {
314	    cJSON *frame = cJSON_CreateObject();
315	    cJSON_AddStringToObject(frame, "type", "mcp");
316	    cJSON_AddStringToObject(frame, "session_id", session_id);
317	    cJSON_AddItemToObject(frame, "payload", resp);   /* frame owns resp */
318	    char *j = cJSON_PrintUnformatted(frame);
319	    if (j != NULL)
320	      {
321	        xiaozhi_ws_send_text(ws, j, strlen(j));
322	        free(j);
323	      }
324	
325	    cJSON_Delete(frame);
326	  }
327	}
