 ****************************************************************************/


#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <spawn.h>
#include <sys/wait.h>
#include <errno.h>

#include <netutils/cJSON.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define MCP_PROTOCOL_VERSION "2024-11-05"
#define MCP_SERVER_NAME       "mcp-server"
#define MCP_SERVER_VERSION    "1.0"

#define MCP_LINE_MAX  2048

/* The fixed list of applications that can be launched. Each entry maps a
 * stable, human-friendly name to the NuttX builtin program name passed to
 * posix_spawn(). Extend this table to expose more apps.
 */
struct app_entry_s
{
  const char *name;   /* name exposed to the LLM via tools/list enum      */
  const char *prog;   /* builtin program name passed to posix_spawn()    */
};

static const struct app_entry_s g_apps[] =
{
  { "hello", "hello" },
};

#define APP_COUNT (sizeof(g_apps) / sizeof(g_apps[0]))

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static cJSON *reply_result(cJSON *id);
static cJSON *reply_error(cJSON *id, int code, const char *message);
static void send_response(cJSON *resp);
static cJSON *handle_initialize(cJSON *id);
static cJSON *handle_tools_list(cJSON *id);
static cJSON *handle_tools_call(cJSON *id, cJSON *params);
static const struct app_entry_s *find_app(const char *name);

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Build a JSON-RPC result object for the given request id. */
static cJSON *reply_result(cJSON *id)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "result", cJSON_CreateObject());
  return resp;
}

/* Build a JSON-RPC error object for the given request id and code/message. */
static cJSON *reply_error(cJSON *id, int code, const char *message)
{
  cJSON *resp = cJSON_CreateObject();
  cJSON *err  = cJSON_CreateObject();
  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
  cJSON_AddItemReferenceToObject(resp, "id", id);
  cJSON_AddItemToObject(resp, "error", err);
  cJSON_AddNumberToObject(err, "code", code);
  cJSON_AddStringToObject(err, "message", message);
  return resp;
}

/* Serialize a JSON-RPC response as one line on stdout (newline-delimited). */
static void send_response(cJSON *resp)
{
  char *json = cJSON_PrintUnformatted(resp);
  if (json != NULL)
    {
      printf("%s\n", json);
      fflush(stdout);
      free(json);
    }

  cJSON_Delete(resp);
}

/* Build a single text content block (the shape tools/call results use). */
static cJSON *make_text_content(const char *text)
{
  cJSON *content = cJSON_CreateArray();
  cJSON *item    = cJSON_CreateObject();
  cJSON_AddItemToArray(content, item);
  cJSON_AddStringToObject(item, "type", "text");
  cJSON_AddStringToObject(item, "text", text);
  return content;
}

static const struct app_entry_s *find_app(const char *name)
{
  for (size_t i = 0; i < APP_COUNT; i++)
    {
      if (strcmp(g_apps[i].name, name) == 0)
        {
          return &g_apps[i];
        }
    }

  return NULL;
}

/* initialize: report server info, protocol version, and capabilities. */
static cJSON *handle_initialize(cJSON *id)
{
  cJSON *resp     = reply_result(id);
  cJSON *result   = cJSON_GetObjectItem(resp, "result");
  cJSON *info     = cJSON_CreateObject();
  cJSON *caps     = cJSON_CreateObject();
  cJSON *toolscap = cJSON_CreateObject();

  cJSON_AddStringToObject(result, "protocolVersion", MCP_PROTOCOL_VERSION);
  cJSON_AddItemToObject(result, "serverInfo", info);
  cJSON_AddStringToObject(info, "name", MCP_SERVER_NAME);
  cJSON_AddStringToObject(info, "version", MCP_SERVER_VERSION);
  cJSON_AddItemToObject(result, "capabilities", caps);
  cJSON_AddItemToObject(caps, "tools", toolscap);
  cJSON_AddBoolToObject(toolscap, "listChanged", false);
  return resp;
}

/* tools/list: advertise the start_app tool and the app name enum. */
static cJSON *handle_tools_list(cJSON *id)
{
