    "例如语音指令\"打开 hello 应用\"时调用此工具。");
  cJSON_AddItemToObject(tool, "inputSchema", schema);

  cJSON_AddStringToObject(schema, "type", "object");
  cJSON_AddItemToObject(schema, "properties", props);
  cJSON_AddItemToObject(props, "app_name", apparg);
  cJSON_AddStringToObject(apparg, "type", "string");
  cJSON_AddStringToObject(apparg, "description", "要启动的应用名称");
  cJSON_AddItemToObject(apparg, "enum", enumv);
  for (size_t i = 0; i < APP_COUNT; i++)
    {
      cJSON_AddItemToArray(enumv, cJSON_CreateString(g_apps[i].name));
    }

  cJSON_AddItemToObject(schema, "required", reqd);
  cJSON_AddItemToArray(reqd, cJSON_CreateString("app_name"));

  cJSON_AddItemToArray(tools, tool);
  cJSON_AddItemToObject(result, "tools", tools);
  return resp;
}

/* tools/call: dispatch by name. Only "start_app" is supported. */
static cJSON *handle_tools_call(cJSON *id, cJSON *params)
{
  cJSON *name = cJSON_GetObjectItem(params, "name");
  const char *namestr = cJSON_IsString(name) ? name->valuestring : NULL;

  if (namestr == NULL)
    {
      return reply_error(id, -32602, "Missing tool name");
    }

  if (strcmp(namestr, "start_app") != 0)
    {
      return reply_error(id, -32601, "Unknown tool");
    }

  cJSON *args     = cJSON_GetObjectItem(params, "arguments");
  cJSON *appname = (args != NULL) ? cJSON_GetObjectItem(args, "app_name") : NULL;
  const char *appstr = cJSON_IsString(appname) ? appname->valuestring : NULL;

  if (appstr == NULL)
    {
      /* MCP convention: return an isError result so the LLM can react. */
      cJSON *resp     = reply_result(id);
      cJSON *result   = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content",
        make_text_content("Missing app_name argument"));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  const struct app_entry_s *app = find_app(appstr);
  if (app == NULL)
    {
      char msg[64];
      cJSON *resp;
      cJSON *result;
      snprintf(msg, sizeof(msg), "Unknown application: %s", appstr);
      resp   = reply_result(id);
      result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content", make_text_content(msg));
      cJSON_AddBoolToObject(result, "isError", true);
      return resp;
    }

  /* Launch the builtin application. argv[0] is the program name. */
  {
    char *argv[2] = { (char *)app->prog, NULL };
    pid_t pid;
    int ret = posix_spawn(&pid, app->prog, NULL, NULL, argv, NULL);
    if (ret != 0)
      {
        char msg[64];
        cJSON *resp;
        cJSON *result;
        snprintf(msg, sizeof(msg), "Failed to launch %s: %d", appstr, ret);
        resp   = reply_result(id);
        result = cJSON_GetObjectItem(resp, "result");
        cJSON_AddItemToObject(result, "content", make_text_content(msg));
        cJSON_AddBoolToObject(result, "isError", true);
        return resp;
      }

    /* Don't wait — let the launched app run independently. */
    {
      char msg[64];
      cJSON *resp;
      cJSON *result;
      snprintf(msg, sizeof(msg), "已启动应用 %s", appstr);
      resp   = reply_result(id);
      result = cJSON_GetObjectItem(resp, "result");
      cJSON_AddItemToObject(result, "content", make_text_content(msg));
      cJSON_AddBoolToObject(result, "isError", false);
      return resp;
    }
  }
}

/* Dispatch one JSON-RPC request object to a handler and return the response. */
static cJSON *dispatch(cJSON *req)
{
  cJSON *method = cJSON_GetObjectItem(req, "method");
  cJSON *id     = cJSON_GetObjectItem(req, "id");
  cJSON *params = cJSON_GetObjectItem(req, "params");
  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;

  if (mstr == NULL)
    {
      return reply_error(id, -32600, "Missing method");
    }

  if (strcmp(mstr, "initialize") == 0)
    {
      return handle_initialize(id);
    }

  if (strcmp(mstr, "tools/list") == 0)
    {
      return handle_tools_list(id);
    }

  if (strcmp(mstr, "tools/call") == 0)
    {
      return handle_tools_call(id, params ? params : cJSON_CreateObject());
    }

  /* Notifications (no id) are not answered. */
  if (id == NULL)
    {
      return NULL;
    }

  {
    char msg[80];
    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
    return reply_error(id, -32601, msg);
  }
}


